(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c39"]=[{"id":"00010354","register_sub_id":"101","register_pk":"199127","name":"福泉坊山門","kana":"ふくせんぼうさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.663278,"lng":132.707598,"geo_status":"db","era":"文政13年(1830)／平成16年移築","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"34-0146","desc":"本堂正面の西方に建つ。間口二・四メートルの一間薬医門で、切妻造桟瓦葺とする。男梁上に三斗を並べて桁と虹梁を受け、軒は二軒繁垂木である。棟通り虹梁上を雲龍彫刻で埋め、虹梁や男梁鼻の絵様繰形を江戸末期らしい華やかなものとして境内正面を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010354"},{"id":"00010353","register_sub_id":"101","register_pk":"199126","name":"福泉坊鐘楼","kana":"ふくせんぼうしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.663103,"lng":132.707634,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造、瓦葺、面積9.4㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"34-0145","desc":"境内西方に本堂と隣接して建つ一間四方の吹放ち鐘楼で、入母屋造桟瓦葺である。切石積基壇上に石製礎盤を置き、丸柱を四方転びに立てて腰貫と頭貫、台輪で固め、尾垂木付の出組を詰組とする。細部絵様や組物の充実した鐘楼で、真宗寺院伽藍を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010353"},{"id":"00010351","register_sub_id":"101","register_pk":"199124","name":"福泉坊本堂","kana":"ふくせんぼうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.662989,"lng":132.707805,"geo_status":"db","era":"昭和23年／平成25年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積404㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0143","desc":"郡山旧城下の境内奥に建ち、桁行一九メートル梁間二一メートル、入母屋造桟瓦葺である。外陣は矢来と柱を省いた広闊な一室とし、内外陣境では七間分の欄間を跨ぐ一対の龍を彫り、外陣組物には斜栱を用いる等、当地で名工と謳われた西谷庄一の力量を示す本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010351"},{"id":"00008572","register_sub_id":"101","register_pk":"134968","name":"佛通寺多宝塔","kana":"ぶっつうじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市高坂町許山30-1","lat":34.45459221,"lng":133.02681857,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積18㎡","structure_material":"木造多宝塔","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0105","desc":"境内の高台に建ち、間口、奥行とも四・三メートル、三間多宝塔、銅板葺で、縁高欄をめぐらす。軸部は和様を基調とし、組物は下層出組、上層四手先とする。蟇股等の細部に流麗な彫刻を施し、軒まわり部材に反りをもたせるなど整った塔姿をもつ近代の多宝塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008572"},{"id":"00014949","register_sub_id":"101","register_pk":"519209","name":"明覚寺山門","kana":"みょうかくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県三次市吉舎町吉舎字七日市462","lat":34.715525,"lng":132.99096111,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0309","desc":"境内東面中央に開く、切妻造桟瓦葺の四脚門。主柱を円柱、控柱を角柱とし、主柱間の冠木の上方に前後の控柱を繋ぐ頭貫を通した特異な形式。台輪上には拳鼻付平三斗を詰組に配し、軒は一軒繁垂木。門口には板戸を吊る。組物賑やかな山門で通りの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014949"},{"id":"00014948","register_sub_id":"101","register_pk":"519208","name":"明覚寺鐘堂","kana":"みょうかくじしょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県三次市吉舎町吉舎字七日市462","lat":34.71543333,"lng":132.99094444,"geo_status":"db","era":"明治25年／昭和中期改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、瓦葺、面積6.8㎡","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0308","desc":"本堂の東南に位置する鐘堂。基壇上に建つ一間四方入母屋造桟瓦葺の南北棟。礎石に円柱を四方内転びに立てて腰貫、頭貫で固めて、三斗を組み、中備は蟇股、軒は一軒繁垂木。内部は竿縁天井を張って梵鐘を吊る。通りに面して建ち、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014948"},{"id":"00014947","register_sub_id":"101","register_pk":"519207","name":"明覚寺本堂","kana":"みょうかくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市吉舎町吉舎字七日市462","lat":34.71554444,"lng":132.99071389,"geo_status":"db","era":"昭和3年／令和2年移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積284㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0307","desc":"石見銀山街道の吉舎宿にある真宗寺院の本堂。東京の両国にあった慈光院本堂を移築したもの。境内に東面して建つ入母屋造桟瓦葺の七間堂で間口の広い向拝を付す。外陣は土間をコの字に廻らした斬新な平面で、小屋組にトラスを用いる。良質な近代和風の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014947"},{"id":"00006713","register_sub_id":"101","register_pk":"107696","name":"明眼寺本堂","kana":"みょうげんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市福富町下竹仁字土井沖488-3","lat":34.526657,"lng":132.742767,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"34 － 0084","desc":"桁行７間梁間９間半、入母屋造桟瓦葺の浄土真宗本堂で、右手奥に８畳２室の座敷を張り出す。正面は吹放ちの広縁とし、正・側面には擬宝珠高欄付の切目縁を廻し、１間向拝を付ける。工匠は安芸高田の西谷庄一で、斜栱に尾垂木を加えるなど独特な組物とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006713"},{"id":"00012648","register_sub_id":"101","register_pk":"367942","name":"赤間神宮水天門及び回廊","kana":"あかまじんぐうすいてんもんおよびかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"山口県","address":"山口県下関市阿弥陀寺町5-2","lat":33.958561,"lng":130.948288,"geo_status":"geocoded","era":"昭和32年／平成2年増築","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"水天門 鉄筋コンクリート造及び木造2階建、銅板葺、建築面積77㎡ 回廊 木造、銅板葺、建築面積25㎡","structure_material":"水天門 鉄筋コンクリート造及び木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"35 － 0098","desc":"壇ノ浦を望む境内正面の石垣上に南面して建つ竜宮造の楼門。入母屋造銅板葺に鴟尾を飾り、東西に回廊を延ばす。鉄筋コンクリート造で上層軸部や組物等を木造とし、腰組に人字形割束を配する。特異な形式と鮮やかな色調で、関門海峡のシンボルとなる大型の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012648"},{"id":"00014204","register_sub_id":"101","register_pk":"508834","name":"川崎観音堂山門","kana":"かわさきかんのんどうさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県周南市川崎二丁目511-1","lat":34.07375556,"lng":131.77957778,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造及び木造二階建、瓦葺、建築面積11㎡","structure_material":"石造及び木造二階建","registered":"2022.02.17(令和4.02.17)","register_no":"35-0106","desc":"山陽道富田にある周防国三十三観音霊場札所の本堂高台下にある竜宮門風の鐘楼門。下層石造、上層木造の二階建入母屋造桟瓦葺平入、二階は角柱に舟肘木で桁を受け、全面に花頭窓を配し、内部は格天井とする。石段や高台上の境内と共に歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014204"},{"id":"00014203","register_sub_id":"101","register_pk":"508833","name":"川崎観音堂本堂","kana":"かわさきかんのんどうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県周南市川崎二丁目511-1","lat":34.07397778,"lng":131.77978889,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"35-0105","desc":"山陽道富田を見渡す高台にある、周防国三十三観音霊場札所の仏堂。入母屋造桟瓦葺平入、妻飾り虹梁大瓶束、軒は出組に隅扇垂木、正面向拝は各所に繰形や彫刻を施す。内部は折上げ格天井、奥に壇を設ける。禅宗様の装飾を丁寧に施す小堂で地域の崇敬を集める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014203"},{"id":"00014205","register_sub_id":"101","register_pk":"508835","name":"川崎観音堂門柱","kana":"かわさきかんのんどうもんちゅう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県周南市川崎二丁目511-1","lat":34.07390833,"lng":131.77974722,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石造、間口2.9m","structure_material":"石造","registered":"2022.02.17(令和4.02.17)","register_no":"35-0107","desc":"山陽道富田にある周防国三十三観音霊場札所の高台を登る石段の先で、本堂正面に位置する石造門柱一対。高さ約二・六メートル、御影石製角柱、江戸切り仕上。柱頭は丸みを帯びた造出しで繰形を施す。後設の照明も意匠に配慮する。高台の境内のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014205"},{"id":"00001534","register_sub_id":"101","register_pk":"102524","name":"錦雲閣","kana":"きんうんかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県岩国市横山2-8内","lat":34.17119276,"lng":132.17627621,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"35 － 0034","desc":"旧岩国藩主吉川家の歴代を祀る吉香神社の絵馬堂。桁行６間梁行４間，身舎５間×３間の入母屋造，桟瓦葺，楼閣風建築で，吉香公園内に偉容を誇る。階下は土間敷で，外周は入口を除き腰を板壁として内側に腰掛縁を設ける。階上は板敷で高欄付切目縁を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001534"},{"id":"00004299","register_sub_id":"101","register_pk":"105289","name":"功山寺総門","kana":"こうざんじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市長府川端1-2-3","lat":33.9956811,"lng":130.98330455,"geo_status":"db","era":"室町時代","year":1454,"year_source":"estimated","year_min":1333,"year_max":1572,"year_label":"室町時代","structure":"木造、瓦葺、間口4.4m","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"35 － 0044","desc":"本柱を棟木際まで延ばす禅宗様の四脚門で，国宝仏殿のある伽藍東側正面にある。円形柱座をもつ礎石に円柱を立て，貫で固め，桁行方向の頭貫位置には舟肘木と軒桁を柱頭に入れ，垂木を受ける。軒廻りは大幅に改変されたが，軸部は室町中期の形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004299"},{"id":"00009830","register_sub_id":"101","register_pk":"195659","name":"護國寺清正公堂","kana":"ごこくじせいしょうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市上田中町2-15-7","lat":33.9635885,"lng":130.94145496,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0074","desc":"本堂南に東面する小堂で、入母屋造桟瓦葺の外陣奥に切妻造の内陣を突出する。外陣に濡縁を廻らせ正面に切妻向拝を設ける。内外陣境は床を上げて結界を設け、最奥の須弥壇は五区分して中央に加藤清正像を祀る。外部は和様で、須弥壇廻りには禅宗様を取入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009830"},{"id":"00009831","register_sub_id":"101","register_pk":"195660","name":"護國寺納骨堂","kana":"ごこくじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県下関市上田中町2-15-7他","lat":33.96352949,"lng":130.94151301,"geo_status":"db","era":"大正10／昭和6頃改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.4㎡、銅製記念塔付","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0075","desc":"境内の南寄りに位置する方二・九メートルの鉄筋コンクリート造で、昭和初期に現在の規模に拡張した。陸屋根で、上部に方円二段の台座上に円筒形の銅製記念塔を載せ、総高五・六メートルとする。外壁は化粧目地入モルタル塗とし、隅柱や背面戸口の額縁を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009831"},{"id":"00003312","register_sub_id":"101","register_pk":"104302","name":"護國寺本堂","kana":"ごこくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市上田中町2-11-10","lat":33.963699,"lng":130.941452,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"35 － 0042","desc":"市街の山裾に東面して建つ日蓮宗の本堂建築。精巧な石積基壇を築き，入母屋造，妻入で，奥行きのある平面とする。比較的細い柱や長押・貫で，平明な外壁をつくり，腰を簓子下見板張とする。正面玄関に設けた唐破風庇が特徴的で，地域景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003312"},{"id":"00009832","register_sub_id":"101","register_pk":"195661","name":"護國寺門柱","kana":"ごこくじもんちゅう","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市上田中町2-15-7","lat":33.96361753,"lng":130.94153205,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"石造門柱2基、間口2.8m","structure_material":"石造門柱2基","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0076","desc":"参道の石段を上り詰めた境内の東正面に開く門で、石製の門柱一対からなる。門柱間二・八メートルで高さ二・七メートルとする。御影石の角柱を瘤出し仕上として各面周囲に平滑面をとり、両柱とも背面に刻銘をもつ。頂部の、丸みを帯びた造り出しが印象的な門柱。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009832"},{"id":"00009381","register_sub_id":"101","register_pk":"194174","name":"春風楼","kana":"しゅんぷうろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県防府市松崎町69-1","lat":34.06305731,"lng":131.57341644,"geo_status":"db","era":"明治6年／昭和59年・平成17年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"35 － 0071","desc":"防府天満宮境内の西南隅に北面して建つ。一七・五メートル四方、二階建、入母屋造桟瓦葺のもと参籠所で、四周に縁を廻らし正面に石階を付す。建設が頓挫した五重塔の部材を引継ぎ、床下廻りに塔初層の組物を使用する。楼閣風で独特な形式になる神社建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009381"},{"id":"00013761","register_sub_id":"101","register_pk":"505321","name":"瑞松庵山門","kana":"ずいしょうあんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県宇部市大字船木字瑞松庵1581","lat":34.04029722,"lng":131.21268889,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、茅葺、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"35 － 103","desc":"入母屋造茅葺の一間楼門。左右に袖塀を付属する。下層は角柱の本柱前後に控柱を立て、三段の貫で繋ぐ。柱間は開放。上層は円柱を立て、桁行三間梁間三間で、四面とも中央間を開放とし、縁に禅宗様高欄を廻らす。小振りながら古刹の表構えの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013761"},{"id":"00012046","register_sub_id":"101","register_pk":"210987","name":"住吉神社唐門及び透塀","kana":"すみよしじんじゃからもんおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市一の宮住吉一丁目1162-2","lat":33.999668,"lng":130.956557,"geo_status":"db","era":"明治34年頃／明治42年増改築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"唐門 木造、檜皮葺、間口2.5m 透塀 木造、こけら葺、総延長79m","structure_material":"唐門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"35-97","desc":"本殿と拝殿の間に建つ檜皮葺の向唐門と左右にのびるこけら葺の透塀。門の本柱は円柱として三斗を組み、虹梁を架ける。控柱は角柱に舟肘木を乗せ、細部には復古的意匠を用いる。透塀は中間に菱格子を組み、上下に吹寄せの襷を付す。繊細な造作の門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012046"},{"id":"00012045","register_sub_id":"101","register_pk":"210986","name":"住吉神社楼門","kana":"すみよしじんじゃろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市一の宮住吉一丁目1162-4","lat":33.999417,"lng":130.956575,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、檜皮葺、建築面積41㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"35-96","desc":"石段上の境内前面に構える三間一戸楼門で、入母屋造檜皮葺。正面に付す奥行一間の庇は当地方から九州に類例が散見される。上層の建ちを抑え、木割が大きく均整のとれた立面などに室町期の前身楼門への指向を示しつつ、細部には明治期らしい華やかさを備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012045"},{"id":"00007135","register_sub_id":"101","register_pk":"108117","name":"大乗寺山門","kana":"だいじょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市長府金屋町17","lat":34.00324852,"lng":130.99053698,"geo_status":"db","era":"江戸末期／平成19移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積35㎡","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"35 － 0060","desc":"旧山陽道に東面して建つ。間口３．６ｍ、１間１戸、切妻造本瓦葺の四脚門で、柱は粽付円柱、組物は出組、軒は二軒繁垂木。両脇に間口１．７ｍ、切妻造本瓦葺、棟門形式の脇門を従える。商工業の町、金屋の玄関口に相応しい規模、構成、意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007135"},{"id":"00007136","register_sub_id":"101","register_pk":"108118","name":"大乗寺鐘楼","kana":"だいじょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市長府金屋町17","lat":34.00347778,"lng":130.99065588,"geo_status":"db","era":"安政5／平成19移築","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"35 － 0061","desc":"山門の北方に位置する。南北棟、入母屋造本瓦葺、桁行１間梁間１間の袴腰付鐘楼で、柱は粽付円柱、組物は出組、軒は二軒繁垂木とし、四周に跳高欄をまわす。寺所蔵の建地割図から「安政五年九月 笹井要蔵」が判明。山門とともに旧山陽道の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007136"},{"id":"00009837","register_sub_id":"101","register_pk":"195666","name":"遠石八幡宮祭器庫","kana":"といしはちまんぐうさいきこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03986732,"lng":131.82324979,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0081","desc":"拝殿の右奥に建つ切妻造平屋建。角柱で腰長押と内法長押を打つ。組物は舟肘木、妻飾は豕扠首で、軒は一軒繁垂木とする。壁は腰上を横板張、腰下を竪板張とし、外側面は透塀に合わせた連子窓形の板壁、内側はガラス入格子引違窓とする。神饌所と形式を揃える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009837"},{"id":"00009838","register_sub_id":"101","register_pk":"195667","name":"遠石八幡宮神饌所","kana":"といしはちまんぐうしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03986732,"lng":131.82302375,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0082","desc":"拝殿の左奥に建つ切妻造平屋建。角柱で腰長押と内法長押を打つ。組物は舟肘木、妻飾は豕扠首で、軒は一軒繁垂木。壁は腰上を横板張、腰下を竪板張とし、外側面は連子窓形の板壁、内側はガラス入格子引違窓とする。祭器庫とともに左右対称の伽藍景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009838"},{"id":"00009840","register_sub_id":"101","register_pk":"195669","name":"遠石八幡宮神門及び袖塀","kana":"といしはちまんぐうしんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408","lat":34.03940035,"lng":131.82308323,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"神門 木造、銅板葺、間口4.2m 袖塀 木造、銅板葺、総延長12m、潜戸付","structure_material":"神門 木造","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0084","desc":"拝殿の正面に建つ四脚門。本柱は円柱で、冠木より上部では虹梁と組んで大瓶束風に見せ、笈形を付す。控柱は角柱で組物は大斗肘木。軒は一軒で、門扉は桟唐戸両開とする。左右袖塀は各三間で中央を脇門とし、脇間に連子窓をたてる。厳格な雰囲気を醸す表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009840"},{"id":"00009839","register_sub_id":"101","register_pk":"195668","name":"遠石八幡宮透塀","kana":"といしはちまんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408","lat":34.0399857,"lng":131.82315581,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、銅板葺、総延長58m、潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0083","desc":"拝殿翼部両端から本殿背後を囲む透塀で、祭器庫と神饌所の妻に取り付く。拝殿翼部寄りに引違戸、本殿背面に両開戸の戸口を設ける。角柱を腰長押と内法長押で固め、腕木で出桁を受け、軒は一軒とする。腰は竪板張で、連子窓には横長六角形断面の連子子を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009839"},{"id":"00009841","register_sub_id":"101","register_pk":"195670","name":"遠石八幡宮手水舎","kana":"といしはちまんぐうてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.0392671,"lng":131.82299995,"geo_status":"db","era":"昭和16／昭和30頃改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、銅板葺、面積3.1㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0085","desc":"神門前方の参道左手に位置する。石製手水鉢の両側に石製基礎を築き、四脚門形式の柱配置とする。本柱、控柱とも角柱で、本柱を棟までのばし、大斗肘木で棟木を受ける。控柱上部を女梁と男梁で繋いで桁を持ち出し、切妻屋根をかける。端正な意匠の手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009841"},{"id":"00009836","register_sub_id":"101","register_pk":"195665","name":"遠石八幡宮拝殿","kana":"といしはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03978701,"lng":131.82313082,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0080","desc":"楼門の左右に翼部をのばし、正背面に構える向拝屋根の拝み部を両翼の棟に重ねる。組物は上層三手先、向拝大斗肘木、翼部舟肘木。軒は上層と向拝が二軒、翼部が一軒である。床は幣殿前半と同高の擬石敷とする。当地方の伝統的な社殿形式を継承した楼拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009836"},{"id":"00009835","register_sub_id":"101","register_pk":"195664","name":"遠石八幡宮幣殿","kana":"といしはちまんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03987029,"lng":131.82314569,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0079","desc":"本殿前面に取付き、桁行四間で後方を床張、前方を擬石敷とし、境に木階二級を設ける。屋根は後方切妻造、前方両下造の段違いで、角柱に舟肘木を載せ、一軒繁垂木とする。側面の半蔀上戸は二つ折りで磨ガラスを用いる。内部架構は虹梁大瓶束笈形付。近代的な幣殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009835"},{"id":"00009834","register_sub_id":"101","register_pk":"195663","name":"遠石八幡宮本殿","kana":"といしはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03994168,"lng":131.82315164,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0078","desc":"三間社流造で庇の側面を前室風に囲み、側背面に縁高欄を廻らせ木階七級を設ける。身舎は円柱に平三斗を、庇は角柱に舟肘木を載せ、身舎側面に板唐戸を、庇に引戸をたてる。妻飾は虹梁大瓶束で華やかな笈形を付し、軒は二軒繁垂木である。上質な近代の神社本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009834"},{"id":"00015250","register_sub_id":"101","register_pk":"530674","name":"長尾八幡宮神饌所","kana":"ながおはちまんぐうしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89419722,"lng":132.26782778,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0127","desc":"中殿南側に位置する神饌所。基壇上に建つ入母屋造妻入桟瓦葺で、東に庇を付して戸口とし、北面に渡廊下を接続。内部は東に玄関土間、西に２室配し、西室は床構付き座敷で、床脇に窓を設けた近代らしい意匠。北側の控所と一対で境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015250"},{"id":"00015252","register_sub_id":"101","register_pk":"530676","name":"長尾八幡宮透塀","kana":"ながおはちまんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89425,"lng":132.26775,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造、銅板葺、総延長25m","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0129","desc":"本殿の南北両脇に延び、本殿域を区画する透塀。切石積基壇上に建つ、切妻造銅板葺で、北・南の端部を西へ一間延ばす。軒は腕木で支持し、柱間に菱格子、欄間に吹寄の襷桟を建て、腰に横板を嵌める。軽快なつくりで、本殿周囲の歴史的な景観に寄与する透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015252"},{"id":"00015248","register_sub_id":"101","register_pk":"530672","name":"長尾八幡宮中殿及び幣殿","kana":"ながおはちまんぐうちゅうでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89432222,"lng":132.26782778,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0125","desc":"本殿と拝殿の間に位置する中殿及び幣殿。切石積基壇上に建つ両下造銅板葺東西棟で中殿の北・南面に下屋を付し、西に幣殿を延ばす。中殿中央は一室の畳敷で北・南に各２室を配し、東の幣殿は床を一段高く張る。天井は竿縁天井。境内景観に欠かせない社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015248"},{"id":"00015253","register_sub_id":"101","register_pk":"530677","name":"長尾八幡宮手水舎","kana":"ながおはちまんぐうちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南2649","lat":33.89432222,"lng":132.26896389,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、面積6.4㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0130","desc":"境内中央、参道の北に建つ切妻造桟瓦葺の手水舎。礎石上に柱を四方転びに立て、虹梁形頭貫で固める。台輪上に大斗肘木を組み、軒は一軒疎垂木。両妻拝に蕪懸魚を付す。内部中央に水盤据え、化粧軒裏を現す。装飾少なく、簡素ながらも境内景観をつくる手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015253"},{"id":"00015255","register_sub_id":"101","register_pk":"530679","name":"長尾八幡宮鳥居","kana":"ながおはちまんぐうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字宮崎11432-1他","lat":33.89348611,"lng":132.269875,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造、間口5.7m、高さ6.9m","structure_material":"石造","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0132","desc":"境内南東の参道入口に建つ石造の明神鳥居。柱間5・7メートル、高さ6・9メートル、内転びの円柱に貫を通し、頂部に反りのある島木と笠木を載せ、正面貫上に社名を刻んだ石製の扁額を掲げる。境内の入口に象徴的に建ち、参道の歴史的な景観を形成する鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015255"},{"id":"00015249","register_sub_id":"101","register_pk":"530673","name":"長尾八幡宮拝殿","kana":"ながおはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89431389,"lng":132.26796667,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0126","desc":"本殿の東に位置する拝殿。基壇上に東面して建つ入母屋造平入銅板葺で正面に千鳥破風を飾り、唐破風造向拝を付し、三方に高欄付縁を廻らす。組物は出組、軒は二軒繁垂木。内部は一室の畳敷で格天井。向拝に籠彫や丸彫彫刻を集中して飾り、外観華やかな拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015249"},{"id":"00015251","register_sub_id":"101","register_pk":"530675","name":"長尾八幡宮控所","kana":"ながおはちまんぐうひかえしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89442778,"lng":132.26784722,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0128","desc":"中殿の北側に位置する控所。基壇上に建つ入母屋造妻入桟瓦葺で、東の戸口に庇を付す。内部は東に玄関土間、西に２室配し、西室は床構付き座敷で床脇に違棚を備える。南面の高欄付縁から渡廊下で中殿に接続する。神饌所と一対で境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015251"},{"id":"00015247","register_sub_id":"101","register_pk":"530671","name":"長尾八幡宮本殿","kana":"ながおはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89432222,"lng":132.26769722,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0124","desc":"周防大島の神南山中腹に位置する神社本殿。基壇上に東面して建つ、三間社流造檜皮葺で、正面に千鳥破風を飾り、切妻造向拝を付す。組物は尾垂木付三手先で通肘木上に斗を並べ、妻飾は二重虹梁大瓶束。軒廻り賑やかで秀逸な彫刻で飾った地元大工による本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015247"},{"id":"00015254","register_sub_id":"101","register_pk":"530678","name":"長尾八幡宮御幸橋","kana":"ながおはちまんぐうみゆきばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南2649","lat":33.89428611,"lng":132.26866389,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造及び石造、橋長4.3m、幅員4.3m、橋台付","structure_material":"鉄筋コンクリート造及び石造","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0131","desc":"境内中央に広がる池に架かる橋。橋長四・三メートル、幅員四・三メートルで、緩やかに反る鉄筋コンクリート造の床版両端に石製高欄を組み、高欄狭間に木瓜状に彫出す石版を嵌める。防火用貯水池建設の一環で架橋し、境内整備の歴史を物語る太鼓橋形式の橋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015254"},{"id":"00003918","register_sub_id":"101","register_pk":"104908","name":"日本基督教団下関丸山教会（旧日本メソヂスト下関教会）会堂","kana":"にほんきりすときょうだんしものせきまるやまきょうかい（きゅうにほんめそぢすとしものせききょうかい）かいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市丸山町4-1-8","lat":33.956921,"lng":130.932526,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積143㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2004.02.17(平成16.02.17)","register_no":"35 － 0043","desc":"関門海峡を一望する高台に建つ。木造，平屋一部２階建で，主室の礼拝堂はキングポストトラス風の小屋組を現した質実な内部構成になる。正面に大きな妻面を見せ，向かって右手に塔屋を付したスパニッシュスタイルの外観は，白壁・赤瓦が印象的な対比をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003918"},{"id":"00007593","register_sub_id":"101","register_pk":"108575","name":"防府天満宮本殿・幣殿・拝殿","kana":"ほうふてんまんぐうほんでん・へいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"山口県","address":"山口県防府市松崎町69","lat":34.0633519,"lng":131.57416276,"geo_status":"db","era":"昭和33","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積211㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"35 － 0067","desc":"入母屋造の本殿と拝殿を両下造の幣殿が繋ぐ複合社殿で、南面する。周囲に組高欄付切目縁をまわし、柱は円柱で、大斗肘木を載せ、二軒繁垂木とする。本殿は桁行三間で、内部を１室とし、正背面中央に両開板戸をたてる。繊細優美な意匠になり、近代社殿建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007593"},{"id":"00013891","register_sub_id":"101","register_pk":"507849","name":"妙鑑寺位牌堂","kana":"みょうかんじいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県山口市大内矢田南八丁目53","lat":34.15191667,"lng":131.51554167,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積88㎡","structure_material":"煉瓦造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"35 － 0104","desc":"桁行一七メートル梁間五メートル煉瓦造平屋建で、屋根は寄棟造赤色桟瓦葺。中央に塔屋が載る。イギリス積を化粧で現し四隅に柱形を付ける。内部は一室で、位牌棚と通路で構成され、天窓からの光が静謐な空間をつくる。煉瓦造の躯体が境内に異彩を放つ位牌堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013891"},{"id":"00006114","register_sub_id":"101","register_pk":"107098","name":"めぐみ幼稚園第一園舎（旧下関バプテスト教会）","kana":"めぐみようちえんだいいちえんしゃ（きゅうしものせきばぷてすときょうかい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市上田中町2-13-26","lat":33.96476634,"lng":130.94102334,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積200㎡、地下室付","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"35 － 0055","desc":"傾斜地に建ち，正面東側に半地下を設けた３廊式教会堂。南側廊部の東端に尖頭屋根を戴く鐘塔を配し玄関とする。外壁は，半地下部を擬石仕上げ，上部をモルタル吹き付けとし，鐘塔に尖頭やチューダーアーチの開口をとる。ヴォーリズ建築事務所設計の教会建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006114"},{"id":"00014089","register_sub_id":"101","register_pk":"508349","name":"有宮神社本殿","kana":"ありみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市西祖谷山村徳善82","lat":33.87796667,"lng":133.77072222,"geo_status":"db","era":"明治41年／昭和41年・平成2年・同15年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"36 - 0215","desc":"大歩危峡右岸の山中、旧街道沿いの尾根上に位置する。一間社流造銅板葺、柱を長押で固め台輪を載せ組物は二手先。正側面に高欄付切目縁を廻し、脇障子を隅行に建てる。脇障子や木鼻、正側面及び庇の虹梁形頭貫の蟇股等、各所を彫刻で飾った、華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014089"},{"id":"00007805","register_sub_id":"101","register_pk":"108786","name":"安楽寺山門","kana":"あんらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.05224191,"lng":134.0617321,"geo_status":"db","era":"宝暦6／昭和11改修","year":1756,"year_source":"db","year_min":1756,"year_max":1756,"year_label":null,"structure":"木造、瓦葺、面積41㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"36-0077","desc":"本堂の南方に建つ、三間三戸二階二重門。入母屋造本瓦葺。上重二軒扇垂木、下重二軒繁垂木。上重が本格的な禅宗様三手先詰組であるのに対し、下重は斗を使わず、肘木や直材を組み合わせる奇抜な組物を用いる。扉上部の中備には奇矯な表情の鬼面を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007805"},{"id":"00007803","register_sub_id":"101","register_pk":"108784","name":"安楽寺書院","kana":"あんらくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.05282482,"lng":134.06183332,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"36-0075","desc":"本堂の北東に東西棟で建つ。入母屋造本瓦葺で、桟瓦葺の下屋庇をまわす。東西に十畳と十二畳半の二室を配し、東・南・西に縁、背面に榑縁を付け、各室にトコやトコ脇、付書院を構え、室境に彫刻欄間を飾る。軽快ながら安定感のある外観をもつ良質な書院座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007803"},{"id":"00007804","register_sub_id":"101","register_pk":"108785","name":"安楽寺鐘楼","kana":"あんらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.0523763,"lng":134.06200959,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造、瓦葺、面積21㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"36-0076","desc":"本堂の東南に位置する。切石積の高い基壇上に建つ方一間吹放ち鐘楼。入母屋造本瓦葺で棟に鯱を飾り、撞木を吊る西側に軒唐破風を付ける。湾曲した方柱を四方転びに建て、三斗組で中備に蟇股を置く。二軒扇垂木とし、内部に格天井を張る。風格のある鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007804"},{"id":"00007807","register_sub_id":"101","register_pk":"108788","name":"安楽寺方丈","kana":"あんらくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町引野字寺ノ西北8他","lat":34.1183368,"lng":134.3885059,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺一部瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"36-0079","desc":"東面する本堂の東北に南面して建つ。屋根は周囲を本瓦葺とする入母屋造茅葺。方柱で、大斗肘木を置き、中備は束で笈形風に彫物を飾る。一軒半繁垂木。内部は田字型に四室を配し、周囲に広縁をまわす。上段の間は藩主の座所と伝える。穏やかな外観になる座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007807"},{"id":"00007802","register_sub_id":"101","register_pk":"108783","name":"安楽寺本堂","kana":"あんらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.05261364,"lng":134.06173036,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積517㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"36-0074","desc":"境内地西寄りに南面して建つ。入母屋造本瓦葺の七間堂、周囲に庇柱を建て、正面に三間向拝を付ける。内部は外陣と矢来の間、内陣等からなる典型的な浄土真宗本堂の形式をもつ。向拝や内外陣境の欄間などに多くの彫物が施される。近代の大規模な真宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007802"},{"id":"00011216","register_sub_id":"101","register_pk":"205323","name":"今宮神社神門及び瑞垣","kana":"いまみやじんじゃしんもんおよびみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻316-1","lat":34.02765187,"lng":133.88044942,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"神門 木造、銅板葺、間口2.7m 瑞垣 木造、鉄板葺、延長48m","structure_material":"神門 木造","registered":"2016.08.01(平成28.08.01)","register_no":"36 - 0132","desc":"本殿と拝殿の間に神門を開け、神門に続いて本殿を囲繞する瑞垣を廻らす。神門は切妻造妻入の一間一戸門で、前面柱筋に上部を菱格子とする桟唐戸を吊る。瑞垣は切石積基壇上に木造で建て、上部を、正面側で菱格子、側背面では縦格子として正面を飾り立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011216"},{"id":"00011215","register_sub_id":"101","register_pk":"205322","name":"今宮神社拝殿","kana":"いまみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻316-1","lat":34.027685,"lng":133.880399,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"36 - 0131","desc":"本殿の正面に建つ方一間入母屋造妻入の建物で、柱間を吹き放して床を張る。天井は格天井、妻には木連格子を嵌める。舞殿とも称され、神楽殿のような使い方も想定されていたとみられる。本殿同様、装飾を抑えた簡明な外観とする。近代の社頭景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011215"},{"id":"00011214","register_sub_id":"101","register_pk":"205321","name":"今宮神社本殿","kana":"いまみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻316-1","lat":34.027603,"lng":133.880532,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"36 - 0130","desc":"伊予街道の旧道から石段を上がった傾斜地に境内を構える。一間社流造の小規模社殿。舟肘木で桁を受け、妻は豕扠首とし、破風に懸魚を付けるほかは装飾要素を抑えた簡素な外観を持つ。設計は徳島県立工業学校の福永嘉吉。煙草産業での繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011214"},{"id":"00011573","register_sub_id":"101","register_pk":"210393","name":"浦山堂","kana":"うらやまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字浦山412-1","lat":34.02298389,"lng":134.05840111,"geo_status":"db","era":"嘉永元年（1848）／昭和43年改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0162","desc":"端四国八十八箇所霊場の第三七番札所。宝形造桟瓦葺の三間堂で、背面寄り中央に一間幅の仏間を設け、四方吹放ちで、四方に縁を廻らし、天井は棹を疎らに配する棹縁天井とする。軒は疎垂木。仏間廻り、側柱上に組物・彫刻を施し、比較的装飾豊かである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011573"},{"id":"00011565","register_sub_id":"101","register_pk":"210498","name":"大泉堂","kana":"おおいずみどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字岡335","lat":34.02769194,"lng":134.07019806,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0154","desc":"端四国八十八箇所霊場の第一三番札所。宝形造本瓦葺の三間堂で、桁行四・〇メートル、梁間三・九メートルの規模の三方吹放ち。中央奥に仏間を張出し、天井は棹縁天井とする。縁を設けない簡易な作りながら、本瓦をもちいるなど重厚な雰囲気を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011565"},{"id":"00010356","register_sub_id":"101","register_pk":"199128","name":"大日孁神社拝殿","kana":"おおひるめじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市山城町光兼字光兼558","lat":33.932177,"lng":133.722551,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"36-0118","desc":"本殿前の一段低い位置の石積基壇上に建つ。桁行三間梁間二間、入母屋造で、内部は畳敷で三室に分かれ、欄間に瓢箪や竹の透彫を嵌める。背面張出しに内拝殿と物入を設ける。木鼻も含めた向拝虹梁彫刻に巻付く龍を表す技法などに、本殿と共通の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010356"},{"id":"00010355","register_sub_id":"101","register_pk":"199273","name":"大日孁神社本殿","kana":"おおひるめじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市山城町光兼字光兼558","lat":33.932152,"lng":133.722641,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"36-0117","desc":"境内奥の石垣に建つ流造本殿。尾垂木付三手先で軒や妻を大きく迫出し、腰組を出組で受け、脇障子を隅行に振る。随所を龍や動植物の彫刻で飾り、特に頭貫木鼻は籠彫の中に人物を彫出し、破風は龍を巻付けた立体的な造形とするなど、高い彫刻技法に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010355"},{"id":"00011570","register_sub_id":"101","register_pk":"210391","name":"皆瀬堂","kana":"かいぜどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字皆瀬190","lat":34.01323111,"lng":134.07697,"geo_status":"db","era":"文化13年（1816）","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0159","desc":"端四国八十八箇所霊場の第三四番札所。宝形造桟瓦葺の三間堂で、北面中央に二間幅の仏間を設け、南・東の二面を吹放ちとして縁を設け、天井は棹縁天井とする。仏間廻りに彫刻を施すほかは全体に簡易な作りとし、地域の信仰の有り様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011570"},{"id":"00007594","register_sub_id":"101","register_pk":"108576","name":"願勝寺山門","kana":"がんしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字願勝寺8","lat":34.05162,"lng":134.06015,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"36 － 0073","desc":"東面する三間一戸八脚門。入母屋造本瓦葺。礎盤上に円柱を建て、出三斗で中備に彫物を置く。柱上部に台輪状の部材を上下２段に設け、その間に笈形付大瓶束や、蓮弁状に上下を作る束などを配する。中央間を花頭形に開け植物文様を飾る。独創的な意匠になる山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007594"},{"id":"00011569","register_sub_id":"101","register_pk":"210501","name":"吉良堂","kana":"きらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字吉良346-3","lat":33.99413,"lng":134.07243611,"geo_status":"db","era":"文化7年（1810）／平成17年改修","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積35㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0158","desc":"端四国八十八箇所霊場の第三〇番札所。寄棟造茅葺（鉄板仮葺）の三間堂で、背面側を三間幅の仏間とし、三方吹放ちの三方に縁を廻らす。正面中央間には虹梁をかけ、天井は棹縁天井とする。背面中央間を円柱とし、随所に彫刻を施し木鼻を付ける。比較的大型の堂宇。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011569"},{"id":"00010691","register_sub_id":"101","register_pk":"201265","name":"西圓寺本堂","kana":"さいえんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県吉野川市鴨島町麻植塚365","lat":34.071657,"lng":134.375937,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0127","desc":"洋行した当時の住職が椅子式仏堂への指向を提唱し、外観にも洋風意匠を取り入れた。内陣部は和風の入母屋造平入とするが、外陣部分は正面入母屋の妻を半切妻形式とし、正面に車寄を付ける。壁は洋風の横板張で壁面に上下窓を配する。独創的な形式の真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010691"},{"id":"00007409","register_sub_id":"101","register_pk":"108391","name":"西教寺経蔵","kana":"さいきょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県美馬市美馬町字宮西13-1","lat":34.052773,"lng":134.06132391,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積47㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"36 － 0071","desc":"本堂の南に東面して建つ。正面に千鳥破風を付ける入母屋造本瓦葺で、唐破風造の前室を設ける。桁行７．１ｍ梁間５．３ｍの土蔵造平屋建で、切石積基礎上を漆喰仕上げとする。前室正面は方柱で柱上に皿斗付三斗を組み、虹梁絵様や笈形などに独特の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007409"},{"id":"00007410","register_sub_id":"101","register_pk":"108392","name":"西教寺山門","kana":"さいきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字宮西13-1","lat":34.052994,"lng":134.061752,"geo_status":"db","era":"天保14","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造、瓦葺、間口3.1m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"36 － 0072","desc":"本堂の前方に建つ、南北棟の三間薬医門。中央に両開桟唐戸を吊り、北間に潜りを設ける。切妻造本瓦葺。本柱上に冠木、男梁を架し、三斗を組み、軒桁や妻の虹梁大瓶束を支える。軒は二軒で、飛檐を雲彫刻の板軒とする特徴的な意匠を見せる。重厚で風格ある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007410"},{"id":"00007408","register_sub_id":"101","register_pk":"108390","name":"西教寺本堂","kana":"さいきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字宮西13-1","lat":34.05298448,"lng":134.06132513,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"36 － 0070","desc":"境内西寄りに東面して建つ。桁行１４ｍ梁間１６ｍ規模で、入母屋造本瓦葺とし、正面に一間向拝、背面に縋破風を付ける。浄土真宗本堂の標準的な平面構成になるが、正面広縁を外陣と一体的に扱う。三斗組を重ねる妻飾りや、向拝の龍虎の彫刻など見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007408"},{"id":"00008589","register_sub_id":"101","register_pk":"134985","name":"地蔵寺経蔵","kana":"じぞうじきょうぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13738786,"lng":134.43179753,"geo_status":"db","era":"文化7年（1810）","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積31㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0092","desc":"本堂の北方に南面して建つ。桁行五・九メートル梁間四・九メートル、寄棟造本瓦葺。切石積基礎上に建つ土蔵で、外壁を漆喰仕上げとし、側面に花頭形の格子窓を穿つ。堂内は板敷で、壁板張、鏡天井を張り、中央に八角の輪蔵を置く。丁寧なつくりの小規模経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008589"},{"id":"00008590","register_sub_id":"101","register_pk":"134986","name":"地蔵寺五百羅漢堂","kana":"じぞうじごひゃくらかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13830368,"lng":134.4314071,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積674㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0093","desc":"本堂など主要伽藍の北方高台に位置する。釈迦堂を中心に大師堂と弥勒堂を対面してコ字形に配し、この間を回廊が繋ぐ。建築面積六七四平方メートル。本瓦葺とし、回廊には背面に接して壇を設けて、羅漢像を安置する。庶民の信仰を集める大規模な境内仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008590"},{"id":"00008588","register_sub_id":"101","register_pk":"134984","name":"地蔵寺大師堂","kana":"じぞうじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.1368286,"lng":134.43230904,"geo_status":"db","era":"正徳年間（1711-1716）／江戸末期改修","year":1714,"year_source":"estimated","year_min":1711,"year_max":1716,"year_label":"正徳年間（1711-1716）","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0091","desc":"本堂の東方に対面して建つ。桁行三間梁間三間、入母屋造本瓦葺で、正面中央に唐破風造の一間向拝を付設。方柱で平三斗とし、彫刻欄間を飾る。二軒繁垂木。内部は後方一間通りを柱列や小壁で間仕切り、厨子を安置する。鏡天井に天女を描くなど、装飾性が強い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008588"},{"id":"00008587","register_sub_id":"101","register_pk":"134983","name":"地蔵寺不動堂","kana":"じぞうじふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13694606,"lng":134.43171117,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0090","desc":"本堂の北側に接して建つ。桁行三間梁間三間で、正面に一間向拝、背面に仏壇を付設する。切妻造本瓦葺。内部は一室で、板敷とし、棹縁天井を張り、中央に護摩壇を置く。方柱で、大斗肘木を置き、一軒繁垂木。二重虹梁大瓶束の妻面に飾られる彫刻が親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008587"},{"id":"00008586","register_sub_id":"101","register_pk":"134982","name":"地蔵寺本堂","kana":"じぞうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13685303,"lng":134.43175505,"geo_status":"db","era":"正徳年間(1711-1716）","year":1714,"year_source":"estimated","year_min":1711,"year_max":1716,"year_label":"正徳年間(1711-1716）","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0089","desc":"境内地の西南に東面して建つ。桁行三間梁間三間で、正面に一間向拝を付け、背面半間通りを取り込む。入母屋造本瓦葺。正面一間通りを外陣、その奥を内陣とし、後方中央に須弥壇を構える。柱は方柱で、隅に絵様肘木を置く。近世に遡る四国札所本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008586"},{"id":"00008784","register_sub_id":"101","register_pk":"149505","name":"常楽寺大師堂","kana":"じょうらくじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町延命606","lat":34.05035061,"lng":134.4759288,"geo_status":"db","era":"文化9年(1812)／平成15年改修","year":1812,"year_source":"converted","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"36 － 0099","desc":"本堂の東北に南面して建つ。宝形造本瓦葺の3間堂。正面に1間向拝を付ける。方柱、木鼻付平三斗、中備蟇股、二軒繁垂木。正面の小壁に彫物を飾る。内部は正面1間通りを外陣、奥を内陣とする。江戸後期に遡る本堂と大師堂が残り、近世四国札所の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008784"},{"id":"00008783","register_sub_id":"101","register_pk":"149504","name":"常楽寺本堂","kana":"じょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町延命606","lat":34.0503593,"lng":134.475666,"geo_status":"db","era":"江戸後期／弘化2年(1845)・昭和63年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"36 － 0098","desc":"辰ヶ山の中腹に東面して建つ。入母屋造本瓦葺の3間堂。正面に1間向拝を付ける。方柱で、平三斗、中備蟇股、二軒繁垂木。内部は正面1間通りを外陣、その奥を内陣とし、中央に須弥壇を構え、厨子を置く。外陣鏡天井に龍が描かれる。近世四国札所本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008783"},{"id":"00011566","register_sub_id":"101","register_pk":"210554","name":"白村堂","kana":"しらむらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字白村194","lat":34.03096611,"lng":134.07422,"geo_status":"db","era":"天保11年（1840）","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積29㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0155","desc":"端四国八十八箇所霊場の第一四番札所。入母屋造茅葺（鉄板仮葺）の三間堂で、四方吹放ちの四方に縁を廻らす。軒は繁垂木とする。中央奥の柱筋より前に仏間を配し、天井は棹縁天井とする。虹梁を配して木鼻を付けるなど、比較的装飾豊かである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011566"},{"id":"00014210","register_sub_id":"101","register_pk":"508840","name":"千光院本堂","kana":"せんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県阿波市土成町吉田字山の神22-3","lat":34.12463611,"lng":134.35234167,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"36-0216","desc":"宮川内谷川の扇頂部に位置する真言宗寺院の本堂。桁行３間梁間４間、切妻造本瓦葺平入の正面に向拝、両側面に下屋、背後に突出部を付す。内部は広い外陣１室で棹縁天井を張る。奥に内陣、内々陣を張出す。イベントにも利用し、当地の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014210"},{"id":"00014087","register_sub_id":"101","register_pk":"508347","name":"蔵珠院茶室","kana":"ぞうしゅいんちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町芝原字宮ノ本3","lat":34.09281944,"lng":134.46276389,"geo_status":"db","era":"江戸末期／平成26年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"36 - 0213","desc":"吉野川右岸の平野に位置する寺院の茶室。本堂西側に建ち、茶室二室と水屋、控室からなる寄棟及び切妻造の棟と、上の間の切妻造棟が棟方向を違えて接続する。部屋ごとに趣を変え、いずれも多様な銘木をふんだんに用い、細部まで意匠を凝らした上質な数寄屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014087"},{"id":"00014088","register_sub_id":"101","register_pk":"508348","name":"蔵珠院まい込み泉","kana":"ぞうしゅいんまいこみいずみ","category":"宗教","subcategory":"その他工作物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町芝原字宮ノ本3","lat":34.09251111,"lng":134.46304722,"geo_status":"db","era":"江戸末期／昭和50年頃・令和2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、直径6m、深さ4.3m","structure_material":"石造","registered":"2021.10.14(令和3.10.14)","register_no":"36 - 0214","desc":"吉野川右岸の平野に位置する寺院の通路付井戸。本堂前方に位置し、上部径約六メートル、深さ約三メートルの擂鉢状の掘込みに螺旋状の通路を設け、底部に径約〇・八メートルの井筒を埋める。壁面は結晶片岩の板状割石を積む。地元に親しまれる類例稀な井戸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014088"},{"id":"00008593","register_sub_id":"101","register_pk":"134989","name":"大山寺回廊","kana":"たいさんじかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15936287,"lng":134.39961426,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0096","desc":"本堂と大師堂を繋ぐ南北棟の廊下。桁行四間梁間三間、切妻造桟瓦葺。梁行に三分し、中央通りを正面に腰壁や格子戸、背面に板壁をたてて間仕切り、壇を設け、三十三観音を安置。正面一間通りを拜所とし、棹縁天井を張る。回廊を信仰の場とした特殊な堂宇である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008593"},{"id":"00008594","register_sub_id":"101","register_pk":"134990","name":"大山寺鐘楼門","kana":"たいさんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15921534,"lng":134.40011394,"geo_status":"db","era":"江戸末期／昭和60年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、銅板葺、建築面積22㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0097","desc":"本堂の前方、石段を降りた位置に東面して建つ。入母屋造の三間一戸楼門で、下層は正面に虹梁を架け間柱を省略する。上層は円柱で、出三斗組、二軒扇垂木。周囲に連子をたてるなど開放的な扱いとし、擬宝珠高欄付縁を張る。大柄で落ち着きのある鐘楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008594"},{"id":"00008592","register_sub_id":"101","register_pk":"134988","name":"大山寺大師堂","kana":"たいさんじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15945329,"lng":134.39962615,"geo_status":"db","era":"文久3年（1863）／昭和60年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0095","desc":"本堂の北方に東面して建つ。正面三間側面二間で、背面に須弥壇を付設し、正・側面に縁をまわす。宝形造で正面に一間向拝を設ける。堂内は板敷、棹縁天井の一室。方柱で、出三斗組とし、軒は一軒の吹寄垂木とする。江戸末期に建立された標準的な弘法大師堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008592"},{"id":"00008591","register_sub_id":"101","register_pk":"134987","name":"大山寺本堂","kana":"たいさんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15927584,"lng":134.39960919,"geo_status":"db","era":"江戸中期／寛政8年（1796）移築・昭和27年・昭和60年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0094","desc":"大山の中腹に伽藍を構える。東面して建つ三間仏堂で、正・側面に縁柱をたてる。入母屋造とし、正面に一間向拝を付設。正面一間通りを外陣、奥を内陣とし、後方に須弥壇や脇壇を置く。木鼻や手挟を龍や貘、植物の彫刻として飾るなど近世らしい装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008591"},{"id":"00009669","register_sub_id":"101","register_pk":"194665","name":"太龍寺護摩堂","kana":"たいりゅうじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88244899,"lng":134.52213588,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0109","desc":"境内東方に南面して建ち、本坊西に接続する。正面三間側面四間、入母屋造銅板葺で、正面向拝一間付、南東面に縁を廻す。前一間を外陣、奥三間は中央間の内陣及び厨子と脇間からなる。粽付円柱を立て、側廻りは台輪上に出組詰組とし、向拝廻りの彫刻密度を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009669"},{"id":"00009674","register_sub_id":"101","register_pk":"194670","name":"太龍寺鐘楼門","kana":"たいりゅうじしょうろうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88213728,"lng":134.52126737,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造、銅板葺、間口5.3m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0114","desc":"本坊から本堂に上る石段途中に東面して建つ。三間一戸楼門、入母屋造銅板葺。下層は貫で固め、台輪上に出組とし、門扉を持たない。梵鐘を吊る上層は周囲竪板壁とし、正背面中央間に花頭窓を開く。組物出三斗、軒は二軒扇垂木とし、彫刻は時代的特色を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009674"},{"id":"00009667","register_sub_id":"101","register_pk":"194663","name":"太龍寺大師堂","kana":"たいりゅうじたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88166377,"lng":134.51997295,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0107","desc":"境内北西方、御影堂の前に東面する。方三間正面向拝一間付で四方に縁を廻す。入母屋造銅板葺、千鳥破風及び軒唐破風付。御影堂を礼拝するための堂で、奥二間を内陣、前一間を外陣とする。虹梁や欄間など随所に瑞獣や波紋などの彫刻を充溢させ装飾的につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009667"},{"id":"00009670","register_sub_id":"101","register_pk":"194666","name":"太龍寺多宝塔","kana":"たいりゅうじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88159239,"lng":134.520337,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積40㎡","structure_material":"木造多宝塔","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0110","desc":"本堂北側の高台に建つ。下層は方三間の周囲に縁を廻らし、組物出組、二軒繁垂木とし、上層は円形平面、四手先組物で二軒扇垂木の軒を支え、上下層とも銅板葺とする。四天柱内を折上格天井とし虚空蔵菩薩を安置する。安定感ある塔姿で、伽藍景観を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009670"},{"id":"00009673","register_sub_id":"101","register_pk":"194669","name":"太龍寺仁王門","kana":"たいりゅうじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88360303,"lng":134.52383719,"geo_status":"db","era":"文化3","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造、銅板葺、間口7.7m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0113","desc":"境内東端に東面して建ち、三間一戸八脚門、入母屋造銅板葺で、両脇間後方に仁王像を安置する。円柱を頭貫と腰貫で固め、台輪上に出三斗を据え、軒は二軒繁垂木とする。中央間には絵様虹梁を架け装飾性を高める。山上伽藍の入口を画すに相応しい意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009673"},{"id":"00009666","register_sub_id":"101","register_pk":"194662","name":"太龍寺本堂","kana":"たいりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88140679,"lng":134.52039411,"geo_status":"db","era":"嘉永5","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0106","desc":"境内の西方に南面して建つ。五間堂規模で正面のみ柱間を広くとり三間とする。入母屋造銅板葺、四方に縁を廻し、正面向拝一間付。内部三間四方を内陣とし、前一間を広い外陣とする。要所を彫刻化した蟇股などで飾り、全体に木太く、当地域の札所の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009666"},{"id":"00009672","register_sub_id":"101","register_pk":"194668","name":"太龍寺本坊","kana":"たいりゅうじほんぼう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88246089,"lng":134.5217623,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積944㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0112","desc":"東半の方丈と西半の庫裏からなり、いずれも入母屋造銅板葺で、間を唐破風屋根の式台玄関で繋ぐ。方丈は九間取の中央を持仏堂とし、前面に入側を配し、欄間には手の込んだ彫刻欄間を入れる。簡素な外観になる大型の本坊で、落ち着いた境内空間を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009672"},{"id":"00009668","register_sub_id":"101","register_pk":"194664","name":"太龍寺御影堂","kana":"たいりゅうじみえいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88165663,"lng":134.51980163,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0108","desc":"境内北西方、大師堂の西方に東面する。正面三間側面二間、宝形造銅板葺で、正側面に縁を廻す。円柱を立て出三斗組、二軒扇垂木とする。堂内は前後二分して内外陣とし、漆塗の厨子を安置する。大師堂とあわせて境内景観に欠かせない堂で、厳粛な雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009668"},{"id":"00009671","register_sub_id":"101","register_pk":"194667","name":"太龍寺六角経蔵","kana":"たいりゅうじろっかくきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88231812,"lng":134.52226675,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡、輪蔵付","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0111","desc":"境内東方に西面して建つ。六角円堂、銅板葺。各隅に五角柱を立て、外壁は腰高に竪板張とし背面三方に棚を張出す。内部の八角輪蔵は禅宗様でまとめられ、二軒扇垂木で極彩色を施し、随所に錺金具を散らす。幕末の華やかな意匠で荘厳された内部空間が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009671"},{"id":"00011571","register_sub_id":"101","register_pk":"210502","name":"竹屋敷堂","kana":"たけやしきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字竹屋敷64","lat":34.01571806,"lng":134.06646389,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0160","desc":"端四国八十八箇所霊場の第三五番札所。宝形造桟瓦葺の三間堂で、背面中央を一間幅の仏間とし、三方吹放ちの四方に縁を廻らす。天井は棹縁天井とする。仏間周りに組物・彫刻を施し、正面中央間に虹梁をかける他は、柱間を貫と長押で固める簡素な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011571"},{"id":"00014960","register_sub_id":"101","register_pk":"519220","name":"立江寺多宝塔","kana":"たつえじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市立江町字若松13","lat":33.96752222,"lng":134.60603611,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造多宝塔、銅板葺及び瓦葺、建築面積31㎡","structure_material":"木造多宝塔","registered":"2024.03.06(令和6.03.06)","register_no":"36 - 0228","desc":"四国霊場十九番札所の境内南方に建つ多宝塔。下層は本瓦葺で方三間の周囲に縁を廻らし組物出組、二軒繁垂木。上層は円形平面で本瓦型銅板葺。四手先組物で軒は二軒扇垂木。内部の四天柱内は折上格天井。板支輪や腰組蟇股の彫刻などが装飾的な近代の多宝塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014960"},{"id":"00012822","register_sub_id":"101","register_pk":"367725","name":"椿八幡神社本殿","kana":"つばきはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市椿町浜1-1","lat":33.92174167,"lng":134.65957194,"geo_status":"db","era":"安政3年(1856)頃","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、檜皮葺(金属板仮葺)、建築面積4.7㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"36 － 191","desc":"市南東部の椿町中心部の境内奥に北面して建つ。一間社流造檜皮葺（鉄板仮葺）で、四周縁を腰組で支持する。組物は柱上の斜め方向にも手先を出す尾垂木付二手先の詰組、妻飾は二重虹梁。組物間や扉回りを彫刻で密に飾る。複雑な構造と豊かな装飾をもつ社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012822"},{"id":"00012990","register_sub_id":"101","register_pk":"368069","name":"釣井薬師堂","kana":"つるいやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県三好市東祖谷釣井107","lat":33.86614722,"lng":133.86609722,"geo_status":"db","era":"文久2年（1862）／昭和33年・平成11年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 195","desc":"祖谷川上流の釣井集落にある三間堂。宝形造銅板葺で、出桁造の一軒疎垂木、四周に切目縁を廻す。内部は板敷の一室で、東正面と両側面東端1間を吹放しとし、西面に張出しの仏壇を設け、各間に桟唐戸を吊る。祖谷渓の歴史的な集落景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012990"},{"id":"00009222","register_sub_id":"101","register_pk":"164775","name":"東福寺本堂","kana":"とうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字木屋341","lat":34.00313675,"lng":134.077586,"geo_status":"db","era":"天保4年(1833)／昭和40年改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積374㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内中央に東面する。桁行26.2メートル梁間13.1メートル、寄棟造本瓦葺で、周囲に下屋を廻らし、正面に唐破風造銅板葺の玄関を構える。東面に広縁を通しその奥を8間取とし、後列南第2間を内陣とする。北寄りはもと庫裏。風格ある外観の真言宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009222"},{"id":"00011568","register_sub_id":"101","register_pk":"210500","name":"長瀬堂","kana":"ながせどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字長瀬196","lat":33.99952,"lng":134.08573,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0157","desc":"端四国八十八箇所霊場の第二八番札所。宝形造桟瓦葺の三間堂で、背面側に仏間を突出させる。四方吹放ちの四周に縁を廻らし、正面中央間は縁を切りこんで木階を設ける。天井は棹縁天井とする。仏間廻りには彫刻を施すが、全体に簡素な意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011568"},{"id":"00009066","register_sub_id":"101","register_pk":"162426","name":"箸蔵寺高灯籠","kana":"はしくらじたかとうろう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.04395506,"lng":133.84186927,"geo_status":"db","era":"明治17年","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造二重灯籠、瓦葺、建築面積15㎡","structure_material":"木造二重灯籠","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0101","desc":"吉野川を俯瞰する丘上に建つ。木造二重灯籠、袴腰付、宝形造桟瓦葺で、北面の出入口に唐破風屋根をかける。下重組物は出組で軒を扇垂木、上重は絵様肘木と二軒繁垂木とする。上層は方一間で、柱や天井を漆喰塗込めとし、四面に花頭窓を開く。特異な形式の木造灯籠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009066"},{"id":"00009068","register_sub_id":"101","register_pk":"162428","name":"箸蔵寺中門","kana":"はしくらじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.04751013,"lng":133.84092402,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0103","desc":"方丈前に東西棟で建つ。切妻造桟瓦葺の一間薬医門で、両脇に袖塀を付ける。五平の本柱を冠木や虹梁形の楣で固め、男梁を四通りに架す。男梁上に大斗肘木を置き、梁や桁を支持。一軒疎垂木で、妻虹梁大瓶束、全面に格天井を張る。規模が大きく威厳ある構え。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009068"},{"id":"00009067","register_sub_id":"101","register_pk":"162427","name":"箸蔵寺手水舎","kana":"はしくらじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.03623358,"lng":133.88784012,"geo_status":"db","era":"明治29年","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、面積6.4㎡、手水鉢付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0102","desc":"本殿東南に位置する。方一間で四方を吹放しとし、軒は二軒繁垂木、屋根は南北棟の入母屋造桟瓦葺である。礎盤上に立てた角柱を頭貫と台輪で固め、組物は出組詰組とする。琵琶板に植物紋様を飾り、手水鉢の四隅を邪鬼で支えるなど、装飾性に富む手水舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009067"},{"id":"00009069","register_sub_id":"101","register_pk":"162429","name":"箸蔵寺仁王門","kana":"はしくらじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.04461903,"lng":133.84202532,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造二階建、瓦葺、建築面積56㎡","structure_material":"木造二階建","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0104","desc":"山の中腹に位置し、南面する。三間一戸二重門、入母屋造桟瓦葺。上・下重とも出組詰組、二軒繁垂木。上重は桁行三間梁間二間、正面中央に両開桟唐戸、両脇間に花頭窓を穿つ。内部は一室で、側・背面に接して壇を構える。近代における禅宗様二重門の優品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009069"},{"id":"00011567","register_sub_id":"101","register_pk":"210499","name":"日浦堂","kana":"ひうらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字日浦72","lat":33.99015306,"lng":134.08206,"geo_status":"db","era":"天明8年（1788）／平成24年改修","year":1788,"year_source":"db","year_min":1788,"year_max":1788,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0156","desc":"端四国八十八箇所霊場の第二六番札所。寄棟造鉄板葺の三間堂で、背面側を三間幅の仏間とし、三方吹放ちの四方に縁を廻らし、正面中央間には向拝一間を設ける。天井は棹縁天井とする。仏間、向拝等に彫刻を施す。仏間の規模が大きく、比較的装飾豊かである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011567"},{"id":"00011572","register_sub_id":"101","register_pk":"210392","name":"引地堂","kana":"ひきちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字引地167","lat":34.02010389,"lng":134.063335,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0161","desc":"端四国八十八箇所霊場の第三六番札所。寄棟造桟瓦葺で、梁間二間桁行二間半。背面中央に一間幅の仏間を設け、四方吹放ちの三方に縁を廻らし、天井は棹縁天井とする。仏間廻り以外は簡素な造りとするが、正面一間を葺下ろして向拝とする点が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011572"},{"id":"00011564","register_sub_id":"101","register_pk":"210553","name":"別所堂","kana":"べっしょどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字別所25-1","lat":34.02349389,"lng":134.06430611,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0153","desc":"端四国八十八箇所霊場の第一一番札所。宝形造の三間堂で、三方吹放ち。中央奥に幅広の仏間を張出し、三方に縁を廻らす。天井は棹縁天井とする。現在は桟瓦葺であるが、第二次大戦前は茅葺であったと伝える。地域信仰の有り様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011564"},{"id":"00004638","register_sub_id":"101","register_pk":"105628","name":"萬福寺蔵","kana":"まんぷくじくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.82283623,"lng":134.47601424,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0052","desc":"境内東方にあり，構造手法から江戸末期と推定される。土蔵造２階建，南北棟の切妻造，桟瓦葺の置屋根式とし，西面に庇付の戸口を設ける。外壁は丁寧な漆喰塗で，腰を押縁下見板張とし，頂部には蛇腹を廻し，妻面の拝みには珍しい松の鰭を付けた懸魚を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004638"},{"id":"00004637","register_sub_id":"101","register_pk":"105627","name":"萬福寺鐘楼","kana":"まんぷくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.82285455,"lng":134.47550286,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積8.7㎡","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0051","desc":"本堂西南にある。方１間の吹放し鐘楼で，二軒繁垂木，入母屋造，本瓦葺である。軸部は角柱を内転びに建て，腰貫・内法貫・頭貫・台輪で結び，三斗を組み，中備蟇股を配する。蟇股や木鼻は独特な形状で地方色があるが，絵様細部は１８世紀中期の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004637"},{"id":"00004639","register_sub_id":"101","register_pk":"105629","name":"萬福寺鎮守堂","kana":"まんぷくじちんじゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.8231147,"lng":134.47555578,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0053","desc":"本堂西に南面してあり，棟札から年代が判明する。乱石積基壇上に建つ１間社見世棚造，板軒，鉄板葺である。身舎は円柱で台輪上に大斗肘木を組み，庇は角柱を虹梁型頭貫で結び，連三斗と中備蟇股をあげる。全体は簡素なつくりだが，境内構成に欠かせない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004639"},{"id":"00004636","register_sub_id":"101","register_pk":"105626","name":"萬福寺本堂","kana":"まんぷくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.82295528,"lng":134.47570332,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0050","desc":"東西に長い境内に南面して建ち，東の庫裏との間に玄関を設ける。方丈形式の６間取平面で，南と西に広縁を設け，柱は角柱，側廻りは舟肘木とする。屋根は寄棟造，もと茅葺で，４周に本瓦葺の下屋を廻す。いわゆる四方蓋民家風の外観に地域性が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004636"},{"id":"00007806","register_sub_id":"101","register_pk":"108787","name":"蓮光寺山門","kana":"れんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県名西郡石井町石井字重松531-1","lat":34.07180924,"lng":134.43204164,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積6.3㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"36-0078","desc":"境内地の南辺中央に建つ。一間一戸楼門で、上部に鐘を吊る。入母屋造本瓦葺。間口２．６ｍに方柱を建て、前寄りに扉口を設ける。上層は円柱で、三斗組、中備蟇股、二軒繁垂木。縁を腕木で支持し、逆蓮の擬宝珠高欄を付ける。端正な外観をもつ小規模の鐘楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007806"},{"id":"00008197","register_sub_id":"101","register_pk":"132638","name":"宇夫階神社齋殿","kana":"うぶしなじんじゃさいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30794352,"lng":133.82085222,"geo_status":"db","era":"文政元年（1818）／昭和6年改修","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0365","desc":"境内中段の南寄りに位置する。桁行９．０ｍ梁間１１ｍの木造平屋建、入母屋造桟瓦葺。田の字型に四室を配し、縁をまわす。西北の部屋にトコや棚、平書院を構え、室境には繊細な欄間を飾るなど良質な書院建築。神仏分離により廃された神宮寺の名残を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008197"},{"id":"00008196","register_sub_id":"101","register_pk":"132637","name":"宇夫階神社雑庫","kana":"うぶしなじんじゃざっこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30805643,"lng":133.82077832,"geo_status":"db","era":"明治中期／昭和9年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0364","desc":"本殿の東南、一段低い位置に建つ。桁行５．０ｍ梁間４．８ｍの２階建土蔵。切妻造本瓦葺で妻入とし、緩い起りの切妻造桟瓦葺の屋根を正面に付ける。腰は目地切をしたモルタル仕上げで、上部は白漆喰仕上げ。小屋組はトラス組。社頭景観を構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008196"},{"id":"00008198","register_sub_id":"101","register_pk":"132639","name":"宇夫階神社社務所","kana":"うぶしなじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30793531,"lng":133.82099797,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0366","desc":"齋殿の東に接続する。入母屋造本瓦葺で、庇を設け、齋殿寄りに入母屋造本瓦葺の式台玄関を付ける。内部は中廊下式で正面側に応接室や事務関係、奥に座敷や居間を配し、西端に土間を設ける。座敷にはトコやトコ脇、平書院を構える。近代的な社務所の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008198"},{"id":"00008194","register_sub_id":"101","register_pk":"132635","name":"宇夫階神社神饌殿","kana":"うぶしなじんじゃしんせんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30811596,"lng":133.82062231,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0362","desc":"拝殿の南隣に東西棟で建つ。桁行三間梁間三間、入母屋造妻入銅板葺。壇正積基壇上に建ち、方柱で舟肘木を置き、一軒疎垂木。正面中央に両開板戸をたて、側面前一間、背面中央一間に格子窓を開け、他は腰板張とする漆喰仕上げの真壁で、平明な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008194"},{"id":"00008193","register_sub_id":"101","register_pk":"132634","name":"宇夫階神社忠魂社本殿","kana":"うぶしなじんじゃちゅうこんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30812007,"lng":133.82039033,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.8㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0361","desc":"本殿の西南に位置し、東面する。高い亀甲積基壇上に建つ入母屋造銅板葺の浜縁付一間社。正側面に高欄付の切目縁をまわし、正面に木階を付ける。出組詰組、二軒繁垂木とするなど、塩竃神社本殿に比べて規模が小さいものの、同様の構造形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008193"},{"id":"00004438","register_sub_id":"101","register_pk":"105428","name":"宇夫階神社本殿（旧多賀宮御正殿）","kana":"うぶしなじんじゃほんでん（きゅうたかのみやごせいでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県綾歌郡宇多津町1644","lat":34.30824493,"lng":133.82045804,"geo_status":"db","era":"昭和28／昭和51移築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0229","desc":"昭和２８年の式年遷宮で造営された豊受大神宮の多賀宮御正殿。次の式年遷宮に際し解体，頒賜された。桁行３間，梁間２間，切妻造の茅葺型銅板葺屋根を架ける。縁を廻さず，棟持柱，堅魚木，千木をもつ正式の神明造で，掘立て柱の伝統的工法をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004438"},{"id":"00008192","register_sub_id":"101","register_pk":"132633","name":"宇夫階神社末社金刀比羅宮拝殿及び幣殿","kana":"うぶしなじんじゃまっしゃことひらぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30867228,"lng":133.82066952,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0360","desc":"塩竈神社本殿の西北に南面して建つ。桁行三間梁間二間、入母屋造本瓦葺で、正面に向拝一間、背面に幣殿を付設する。内部は拭板敷で、棹縁天井を張り、正面に縁を付ける。向拝のみ三斗組とし、中備に波紋彫刻を置く。身舎は組物などを省略し簡明な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008192"},{"id":"00008191","register_sub_id":"101","register_pk":"132632","name":"宇夫階神社末社塩竈神社拝殿及び幣殿","kana":"うぶしなじんじゃまっしゃしおがまじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30835615,"lng":133.82080501,"geo_status":"db","era":"昭和9年／昭和60年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0359","desc":"塩竈神社本殿の正面に位置する。桁行三間梁間二間の入母屋造銅板葺で、正面に軒唐破風付一間向拝を付設。背面に桁行三間梁間三間切妻造の幣殿を突出する。正面中央に双折桟唐戸、両脇に蔀戸を装置する。安定感のある外観で、向拝の龍や鳳凰の彫刻は出色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008191"},{"id":"00008190","register_sub_id":"101","register_pk":"132631","name":"宇夫階神社末社塩竈神社本殿","kana":"うぶしなじんじゃまっしゃしおがまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30842389,"lng":133.82077011,"geo_status":"db","era":"昭和9年／昭和60年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0358","desc":"小丘に占める境内の最上段、本殿の北方に位置し、高い亀甲積基壇上に建つ。桁行一間梁間一間、入母屋造、向拝一間、銅板葺の社殿で、正面に千鳥破風と軒唐破風を付ける。本支輪付の出組詰組とし、要所に彫物を飾る。二軒繁垂木。瀟洒ながら本格的な仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008190"},{"id":"00008195","register_sub_id":"101","register_pk":"132636","name":"宇夫階神社神輿蔵","kana":"うぶしなじんじゃみこしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30790247,"lng":133.82042113,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積52㎡","structure_material":"土蔵造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0363","desc":"本殿の南方に位置し北面する。桁行９．６ｍ梁間４．８ｍの土蔵造、切妻造本瓦葺。石積基壇上に建ち、腰を黒色のモルタル仕上げ、上部を白漆喰仕上げとする。腰内部は二室に間仕切り、それぞれに緩い起りの切妻造銅板葺の庇を付けて、硬質な外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008195"},{"id":"00000103","register_sub_id":"101","register_pk":"101093","name":"金刀比羅宮宝物館","kana":"こんぴらぐうほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町892-1","lat":34.18455385,"lng":133.81316693,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造2階建、瓦葺、建築面積165㎡","structure_material":"石造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0004","desc":"石造，２階建の宝物館で，文部省技師久留正道の設計である。入母屋造，本瓦葺の屋根や唐破風造の玄関等をもつ一方，アーチ窓や石組による目地等を用いる。日本人建築家が，伝統的な建築に本格的な洋風の意匠を持ち込んだ初期の事例として注目できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000103"},{"id":"00012247","register_sub_id":"101","register_pk":"353047","name":"讃留霊王神社玉垣","kana":"さるれおじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県丸亀市飯山町下法軍寺1459","lat":34.24734,"lng":133.849979,"geo_status":"db","era":"江戸末期／明治後期増設","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長20m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"37-429","desc":"神社の御神体である円墳、讃留霊王古墳の墳頂部を方形に画す玉垣。花崗岩製、総延長二〇メートルで、正面に当たる東側を開いて幣殿との間を通路状に結ぶ。特徴的な構成をとる神社を象徴するとともに、地域の歴史的景観を形成する玉垣である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012247"},{"id":"00012248","register_sub_id":"101","register_pk":"353048","name":"讃留霊王神社鳥居","kana":"さるれおじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県丸亀市飯山町下法軍寺1459","lat":34.247417,"lng":133.850315,"geo_status":"db","era":"文政13年(1830)","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"石造、間口2.2m、高さ2.9m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"37-430","desc":"境内東端部の入口から拝殿・幣殿へと上がる階段の中ほどに建つ石造明神鳥居。間口二・二メートルで、柱をやや内転びで立て、島木と反りの強い笠木で結ぶ。柱に「文政十三年」と彫られており年代も明らかで、境内の歴史的景観を今に伝える鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012248"},{"id":"00012246","register_sub_id":"101","register_pk":"353046","name":"讃留霊王神社幣殿","kana":"さるれおじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市飯山町下法軍寺1459","lat":34.247359,"lng":133.850063,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"37-428","desc":"丸亀市南方平野部の小高い丘陵上に位置する。入母屋造平入、檜皮葺の一間社で、円柱上に二手先を組み、軒は二軒扇垂木とし、四方に縁を廻らす。背面側の讃留霊王古墳を御神体とし、正面だけでなく背面側にも桟唐戸を設ける点が特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012246"},{"id":"00014414","register_sub_id":"101","register_pk":"511403","name":"三所神社幣拝殿","kana":"さんしょじんじゃへいはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市本島町生ノ浜字浦内635","lat":34.38158333,"lng":133.76031111,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0465","desc":"塩飽諸島本島の生ノ浜浦に所在する神社の拝殿及び弊殿。正面三間側面二間、入母屋造本瓦葺、正面に千鳥破風、唐破風向拝を重ねる。背面に弊殿を張り出し、本殿と接続する。水引虹梁、蟇股、手挟、向拝の彫刻に技量を示す。塩飽大工活動末期の社殿として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014414"},{"id":"00014413","register_sub_id":"101","register_pk":"511402","name":"三所神社本殿","kana":"さんしょじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県丸亀市本島町生ノ浜字浦内635","lat":34.38160556,"lng":133.76038333,"geo_status":"db","era":"天保元年（1830）","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0464","desc":"塩飽諸島本島の生ノ浜浦に所在する神社本殿。一間社流造、本瓦葺で二重切石基壇、亀腹上に建つ。正側面に高欄付切目縁を廻らし、身舎両袖に脇障子を建てる。板支輪の彫刻、手挟や木鼻の丸彫彫刻等、いずれも巧緻で躍動感があり塩飽大工の力量が示される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014413"},{"id":"00002442","register_sub_id":"101","register_pk":"103432","name":"清水観音堂","kana":"しみずかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡土庄町豊島唐櫃字東伏1261-3","lat":34.48555743,"lng":134.08544038,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0058","desc":"共同用水場南側の階段上にある桟瓦葺，切妻造の観音堂。桁行と梁間は約４ｍで，前方に向拝を張り出す。後方に仏壇，その右側に附属屋を設ける。簡素な建物であるが，当地域での水と信仰との結びつきを物語り，水利施設と一体の独特の空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002442"},{"id":"00002443","register_sub_id":"101","register_pk":"103433","name":"清水神社社殿","kana":"しみずじんじゃしゃでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町豊島唐櫃字東状1261-2","lat":34.48574733,"lng":134.08531107,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0059","desc":"共同用水場西方の階段上段にある，本瓦葺，前方入母屋造の社殿。石造基礎の上に，梁間４ｍ，桁行３ｍ，外装杉板張の建家が立ち上がり，後方に板石を積んだ約１ｍ幅の祭壇を張り出す。小屋梁の墨書により，大正２年造と知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002443"},{"id":"00012833","register_sub_id":"101","register_pk":"367736","name":"正蓮寺大玄関及び小玄関","kana":"しょうれんじおおげんかんおよびしょうげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"弘化2年（1845）／昭和28年頃・平成27年改修","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 440","desc":"本堂の東側に接続し、西に入母屋造妻入の大玄関、東に両下造の小玄関を配し、東面を庫裏に接続する。大玄関は式台を構えて奧に三室を並べ、最奧を座敷とする。小玄関は渡廊下を兼ね、後方に控室を設ける。本堂、庫裏と並び建ち、境内の景観を重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012833"},{"id":"00012835","register_sub_id":"101","register_pk":"367738","name":"正蓮寺経蔵","kana":"しょうれんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"明治12年／平成4年・同10年頃改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積26㎡","structure_material":"土蔵造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 442","desc":"境内前方の山門東脇に北面して建つ。六角形平面の本瓦葺で、切妻造起り屋根の向拝を付す。外壁は柱形を表した大壁造で、正面に扉口、西面に花頭窓を設け、向拝は動物の具象的な彫刻で賑やかに飾る。参道を挟んで鐘楼と並び建ち、境内の表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012835"},{"id":"00012836","register_sub_id":"101","register_pk":"367739","name":"正蓮寺山門","kana":"しょうれんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 443","desc":"境内南面の西寄りに建つ。切妻造本瓦葺の薬医門で、親柱は大断面の五平材を用い、控柱も木太い角柱に絵様付の虹梁を渡すなど量感あるつくりとする。軒は二軒半繁垂木、妻飾は笈形付大瓶束で蕪懸魚を吊る。境内の江戸中期の建築形式を伝える貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012836"},{"id":"00012834","register_sub_id":"101","register_pk":"367737","name":"正蓮寺鐘楼","kana":"しょうれんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、面積8.9㎡","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 441","desc":"境内前方の山門西脇に東面して建つ。入母屋造本瓦葺の吹放し鐘楼で、布積基壇に反りのある角柱を内転びで立て、三段に通した貫で固める。組物は二重尾垂木付三手先の詰組、軒は二軒扇垂木である。均整のとれた禅宗様建築で、境内の表構えを引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012834"},{"id":"00012832","register_sub_id":"101","register_pk":"367735","name":"正蓮寺本堂","kana":"しょうれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"文政8年（1825）／平成4年・同28年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積332㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 439","desc":"市西部の五色台西麓にある真宗寺院。本堂は南正面の入母屋造本瓦葺、向拝一間付。内部を円柱、側廻りを角柱とし、向拝は木鼻に龍や獏を彫刻し、虹梁には波に鯉の躍動的な文様をあしらうなど装飾豊かに仕上げる。讃岐地方の江戸後期真宗本堂の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012832"},{"id":"00007928","register_sub_id":"101","register_pk":"108908","name":"善通寺釈迦堂","kana":"ぜんつうじしゃかどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22634176,"lng":133.77679782,"geo_status":"db","era":"延宝年間／天保2移築・昭和45年改修","year":1677,"year_source":"estimated","year_min":1673,"year_max":1681,"year_label":"延宝年間","structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0328","desc":"金堂の南東に位置する。桁行五間梁間六間、入母屋造、向拝一間軒唐破風付、本瓦葺。堂内は中央背面に接して仏壇を構え、前方に板敷を設けて内陣とし、三方に外陣をめぐらす。四周に縁を付け、方柱で舟肘木、引違い舞良戸をたてるなど、住宅風仏堂の特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007928"},{"id":"00007931","register_sub_id":"101","register_pk":"108911","name":"善通寺鐘楼","kana":"ぜんつうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22596521,"lng":133.77629781,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0331","desc":"金堂の南西に建つ鐘楼で、桁行三間梁間二間、袴腰付、入母屋造本瓦葺である。挿肘木と虹梁上の三斗で擬宝珠高欄付縁を支持し、上層は組物を平三斗組として扇垂木で総反りの軒を受ける。もと鐘楼門であった痕跡をとどめる鐘楼で、境内景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007931"},{"id":"00008178","register_sub_id":"101","register_pk":"132619","name":"善通寺誕生院閻魔堂及び渡廊下","kana":"ぜんつうじたんじょういんえんまどうおよびわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22564022,"lng":133.77432037,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0346","desc":"護摩堂と東の親鸞堂を繋ぐ渡廊下。桁行五間梁間一間、切妻造桟瓦葺。中央三間は南面を開放、北面は屋根を葺き降ろして奥行一間の閻魔堂を造り、蔀戸を吊る。両端一間は北面が真壁造で連子窓を開け、南面は腰壁。基本的に廻廊と同じ意匠で、統一感をもたせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008178"},{"id":"00008171","register_sub_id":"101","register_pk":"132612","name":"善通寺誕生院奥殿","kana":"ぜんつうじたんじょういんおくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22497607,"lng":133.77393569,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0339","desc":"誕生院伽藍の中央に東面して建ち、釣屋を介して御影堂に続く。方三間、宝形造本瓦葺。四周に縁をまわし、円柱で、平三斗組とし、中央間に蟇股を飾る。正面中央間は唐破風屋根を付け、厨子風に造り、彫刻や彩色で飾る。繊細優美な姿で、厳粛な雰囲気を醸し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008171"},{"id":"00008186","register_sub_id":"101","register_pk":"132627","name":"善通寺誕生院極楽堀石積","kana":"ぜんつうじたんじょういんごくらくほりいしづみ","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22565782,"lng":133.77477393,"geo_status":"db","era":"明治22年","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造、延長193m、柵付","structure_material":"石造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0354","desc":"誕生院境内の東端に、深さ１．３ｍ、幅６．５ｍ、南北９０ｍに及ぶ極楽堀が掘られる。四周に切石を積み上げて擁壁を造り、延長１９３ｍを測る。通り側に構える石柵は、布石上に方形の柵子を建て、六本おきに太くし、その間に笠石を載せる。堅固な構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008186"},{"id":"00008175","register_sub_id":"101","register_pk":"132616","name":"善通寺誕生院護摩堂","kana":"ぜんつうじたんじょういんごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.2255646,"lng":133.77424475,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0343","desc":"聖霊殿の東北に南面して建つ。正面三間側面三間で、内・外陣からなり、周囲に縁をまわす。宝形造銅板葺の二重屋根とし、正面に向拝一間を付ける。円柱、平三斗組で、中備に間斗束を置く。軒は二軒疎垂木。木鼻や蟇股、肘木などに復古的な細部意匠を採用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008175"},{"id":"00008177","register_sub_id":"101","register_pk":"132618","name":"善通寺誕生院護摩堂廻廊","kana":"ぜんつうじたんじょういんごまどうかいろう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22546268,"lng":133.77400802,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0345","desc":"聖霊殿から地蔵堂の側・背面を通り、護摩堂に至る廊下。切妻造銅板葺、地蔵堂側を開放、北・西面は真壁造で連子窓を設け、出入口を一ヶ所開ける。方柱で、舟肘木を置き、梁間に虹梁を渡し、蟇股で棟木を支持。土間床で化粧屋根裏天井とし、閑静な空間を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008177"},{"id":"00008176","register_sub_id":"101","register_pk":"132617","name":"善通寺誕生院地蔵堂","kana":"ぜんつうじたんじょういんじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22552844,"lng":133.77407378,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0344","desc":"護摩堂の西に位置し、南面する。両脇間が狭い方三間仏堂。宝形造銅板葺で正面に軒唐破風を付ける。周囲に葛石をまわし、切石礎石上に方柱を建て、舟肘木を置く。一軒疎垂木。土間で、格天井を張り、中央に石造地蔵を安置する。勾配の緩い、穏やかな外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008176"},{"id":"00008174","register_sub_id":"101","register_pk":"132615","name":"善通寺誕生院聖霊殿","kana":"ぜんつうじたんじょういんしょうりょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22535089,"lng":133.77406392,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺及び檜皮葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0342","desc":"御影堂の北に並び立ち、桁行三間の渡廊下で繋がる。宝形造銅板葺で、四周に檜皮葺の裳階をまわし、正面の中央間を切り上げ、銅板葺とする。正面三間側面四間とし、内・外陣に分け、小組格天井を張る。方柱で舟肘木、緩やかな一軒疎垂木を配る端正な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008174"},{"id":"00008179","register_sub_id":"101","register_pk":"132620","name":"善通寺誕生院宸殿","kana":"ぜんつうじたんじょういんしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22460454,"lng":133.77441243,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0347","desc":"御影堂の南方に建つ東西棟の入母屋造桟瓦葺。桁行２０ｍ梁間１１ｍで、組高欄付の切目縁を三方にまわす。南北各四室からなる八間取で、北面に畳廊下を付設する。南面西端間が上段の間で、トコや棚を構え、二重折上小組格天井とする。規模が大きく、風格がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008179"},{"id":"00008180","register_sub_id":"101","register_pk":"132621","name":"善通寺誕生院大玄関及び小玄関","kana":"ぜんつうじたんじょういんだいげんかんおよびしょうげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22470976,"lng":133.77458669,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積201㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0348","desc":"宸殿の東に取り付き、北側に大玄関、南に小玄関を配する。大玄関は入母屋造妻入瓦葺で、正面に軒唐破風を付ける。式台を設け、天井は二重折上小組格天井とする。小玄関は入母屋造で、格天井として、両脇間に花頭窓を開ける。宸殿正面に格調ある構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008180"},{"id":"00008185","register_sub_id":"101","register_pk":"132626","name":"善通寺誕生院太鼓塀","kana":"ぜんつうじたんじょういんたいこべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22526541,"lng":133.77494178,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、延長61m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0353","desc":"勅使門の南北に延び、北は番所に、南は通用口に至る。折曲り総延長６１ｍに及ぶ。極楽堀に接する場所は護岸石積上に、その他は切石基礎上に建ち、勅使門の袖部分では高さ２．７ｍ、他は２．３ｍを測る。本瓦葺とし、五線の定規筋を入れ、格式が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008185"},{"id":"00008189","register_sub_id":"101","register_pk":"132630","name":"善通寺誕生院勅使橋","kana":"ぜんつうじたんじょういんちょくしばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22518321,"lng":133.77505685,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造桁橋、橋長6.5m、幅員3.6m、脚柱付","structure_material":"石造桁橋","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0357","desc":"勅使門の東、極楽堀に架かる。石造桁橋で、中央に橋脚を建てる。橋長６．５ｍ、幅員３．６ｍ。緩やかに起る太鼓橋で、擬宝珠高欄を付ける。擬宝珠柱は両側に各八本ずつ建て、柱身に対して宝珠が大きく、斗束も分銅形にするなど、装飾的な要素が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008189"},{"id":"00008184","register_sub_id":"101","register_pk":"132625","name":"善通寺誕生院勅使門","kana":"ぜんつうじたんじょういんちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22515033,"lng":133.77496151,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、銅板葺、間口3.0m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0352","desc":"仁王門の南方、大玄関の東北に位置する四脚門。前後唐破風造側面切妻造の銅板葺。本柱を円柱、控柱を几帳面取方柱とし、三斗組で、正・背面中備に蟇股を置く。周囲に葛石をまわし、土間床とし、全面に格天井を張る。緩やかな屋根勾配で、優雅な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008184"},{"id":"00008182","register_sub_id":"101","register_pk":"132623","name":"善通寺誕生院仁王門","kana":"ぜんつうじたんじょういんにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.2253476,"lng":133.77474451,"geo_status":"db","era":"明治22年／昭和50年修理","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0350","desc":"御影堂の東に位置する三間一戸八脚門。入母屋造本瓦葺とし、棟に鯱を飾る。大斗肘木。二軒繁垂木で鏡天井を張り、床は石敷。両脇間には石積基礎を設け、正面側に金剛柵を付け、金剛力士像を安置し、背面には大草鞋を飾る。規模が大きく、力強い外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008182"},{"id":"00008188","register_sub_id":"101","register_pk":"132629","name":"善通寺誕生院二十日橋","kana":"ぜんつうじたんじょういんはつかばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22543309,"lng":133.7748826,"geo_status":"db","era":"昭和17年／昭和後期移設","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"石造桁橋、橋長6.8m、幅員5.4m、脚柱付","structure_material":"石造桁橋","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0356","desc":"仁王門の東、極楽堀に架かる。明治以前は毎月二十日のみ橋の通行が許されたと伝え、その由来でこの名がある。石造桁橋で、中央に橋脚を建てる。橋長６．８ｍ、幅員５．４ｍ。緩やかな太鼓橋で、擬宝珠高欄を付け、岸上では外に開く。伝統的な石橋の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008188"},{"id":"00008183","register_sub_id":"101","register_pk":"132624","name":"善通寺誕生院番所","kana":"ぜんつうじたんじょういんばんしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22529828,"lng":133.77477081,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.3㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0351","desc":"仁王門の南に南北棟で建つ。桁行４．０ｍ梁間２．３ｍの木造平屋建。緩い起りを付ける入母屋造で本瓦を葺く。仁王門寄りの東面半間と北面に銅板葺庇付の出格子窓を付ける。腰に下見板を張り、真壁造。内部は一室で、畳敷とする。誕生院伽藍の正面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008183"},{"id":"00008187","register_sub_id":"101","register_pk":"132628","name":"善通寺誕生院弁天社","kana":"ぜんつうじたんじょういんべんてんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22551857,"lng":133.77482999,"geo_status":"db","era":"慶応3年(1867)","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0355","desc":"極楽堀のなか、二十日橋の北側に西面して建つ。石造の基礎組上に建つ一間社流造、本瓦葺。小規模な社殿で、側・背面板壁とし、正面に両開桟唐戸をたてる。縁を張らず、正面に木階を付ける。三斗組で、向拝の中備や木鼻に彫刻を飾る。堀に建つ特徴的な景観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008187"},{"id":"00008172","register_sub_id":"101","register_pk":"132613","name":"善通寺誕生院御影堂","kana":"ぜんつうじたんじょういんみえどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22513974,"lng":133.77424548,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積554㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0340","desc":"奥殿の前に建つ。前寄りで十字形に入母屋屋根が交叉し、正面に三間向拝を付ける。前方は桁行七間梁間四間で外陣とし、その奥に桁行六間梁間五間の内陣を付設、周囲に縁をまわす。組物は平三斗。内部は内・外陣とも格天井を張り、平明で広い礼拝空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008172"},{"id":"00008173","register_sub_id":"101","register_pk":"132614","name":"善通寺誕生院御影堂前廻廊","kana":"ぜんつうじたんじょういんみえどうまえかいろう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22526212,"lng":133.7745571,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0341","desc":"御影堂前に位置する、東西棟の本瓦葺建物。桁行九間梁間一間で吹き放ち、妻を唐破風造とする。礎石上に几帳面取方柱を建て、柱上に三斗を組み、虹梁形頭貫で固め、大瓶束が棟木を支持する。梁間中備の龍彫刻や、柱の貘鼻、獅子鼻が重畳し、御影堂の参道を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008173"},{"id":"00008181","register_sub_id":"101","register_pk":"132622","name":"善通寺誕生院南土蔵","kana":"ぜんつうじたんじょういんみなみどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22421,"lng":133.77408693,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0349","desc":"伽藍の南西隅に位置する。南北棟の切妻造桟瓦葺の置屋根。高く切石を積み上げて基礎とし、壁は白漆喰仕上げ。北面に両開戸を装置し、東・西面に窓を穿つ。内部は板敷で、壁を板張とする。１階は引違い戸をたて南一間を間仕切る。装飾的要素を廃した簡明な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008181"},{"id":"00007929","register_sub_id":"101","register_pk":"108909","name":"善通寺天神社","kana":"ぜんつうじてんじんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22655164,"lng":133.77642538,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0329","desc":"金堂の北東に祀られた小規模な一間社流見世棚造。切石積基壇上に建ち、土台上に方柱を建てて、舟肘木を置き、桁を受け、一軒繁垂木、本瓦を葺く。外壁は横板張とする。周囲を石柵で囲い、正面に石鳥居を建てて、寺院境内社としての風致を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007929"},{"id":"00007933","register_sub_id":"101","register_pk":"108913","name":"善通寺中門","kana":"ぜんつうじなかもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22584175,"lng":133.77571962,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積27㎡、袴腰付","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0333","desc":"境内の西辺中央、釈迦堂の正面に建つ。一間一戸楼門、入母屋造本瓦葺である。下層では左右に袴腰状の板壁を設け、虹梁には雲龍や鶴を彫る。上層は桁行三間梁間二間とし、吹き放つ。軒は総反りで垂木を扇に配り、優美な意匠とする。特異な外観をもつ門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007933"},{"id":"00007932","register_sub_id":"101","register_pk":"108912","name":"善通寺南大門","kana":"ぜんつうじみなみだいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22565863,"lng":133.77670728,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、瓦葺、間口7.6m、左右袖塀付","structure_material":"木造","registered":"2009.11.02(平成21.11.02)","register_no":"37-0332","desc":"境内の南辺中央、金堂の正面に建ち、間口７．６ｍの門の左右に矩折れに延ばした袖塀に潜りを開く。高麗門形式の平唐門で、前後に軒唐破風を付け、本瓦を葺く。建ちが高く、左右の螻羽の出も深く、役物瓦の意匠も見応えがあり、古刹の正門に相応しい風格を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007932"},{"id":"00007930","register_sub_id":"101","register_pk":"108910","name":"善通寺龍王社","kana":"ぜんつうじりゅうおうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22651871,"lng":133.77560851,"geo_status":"db","era":"文化5／文久元改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0330","desc":"境内北西にある池の小島に所在。規模の小さな一間社流造、本瓦葺である。野面積基壇上に土台を設け、方柱を建て三斗を組む。一軒疎垂木で、妻は虹梁大瓶束。妻の中備を雲紋彫刻、向拝の中備を波頭紋とするなど、雨乞祈願のための社らしい意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007930"},{"id":"00002691","register_sub_id":"101","register_pk":"103681","name":"乃木神社鳥居","kana":"のぎじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22559606,"lng":133.78057178,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、高さ3m、幅3m","structure_material":"石造","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0089","desc":"手水舎の北東方，四国学院大学方面から入る参道のほぼ中央，参道が社務所前でクランク状になる手前側に建つ。柱径５５ｃｍの御影石を用いた石造鳥居で，柱間５ｍほどの規模。神明造の本殿に対応して，直線材を用い貫が柱内に納まる神明鳥居の形式を採る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002691"},{"id":"00002688","register_sub_id":"101","register_pk":"103678","name":"乃木神社拝殿","kana":"のぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22535661,"lng":133.77995231,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0086","desc":"本殿と同様に切石積基壇の上に建ち，正面５間の中央３間を入口とし，西面本殿側に幣殿を，北西方に祭器庫を突出させる。屋根は銅板葺で，棟を千木と勝男木で飾り，正面屋根に千鳥破風をつくっているが，全体的に神明造風の簡潔な直線的造形で統一されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002688"},{"id":"00002687","register_sub_id":"101","register_pk":"103677","name":"乃木神社本殿","kana":"のぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22530614,"lng":133.77984631,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0085","desc":"もと歩兵第４３連隊跡地の北側に位置し，切石積基壇上の亀腹の上に東面して建つ。棟持柱を持つ三間社神明造の本殿で，柱は円柱，屋根は銅板葺とする。木部は全体に素木で，正面に桁行梁間とも１間の両下造向拝を設け，正面階及び本殿四周に高欄を廻らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002687"},{"id":"00010366","register_sub_id":"101","register_pk":"199138","name":"萩原寺大門及び番所","kana":"はぎわらじおおもんおよびばんしょ","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2742-1","lat":34.070929,"lng":133.687356,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"大門 木造、瓦葺、間口3.3m、左右袖塀及び潜戸付 番所 木造平屋建、瓦葺、建築面積18㎡","structure_material":"大門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0406","desc":"境内西側本坊の客殿正面に位置する。大門は切妻造本瓦葺の四脚門で左右に袖塀を続けて潜戸を開く。ケヤキ造で妻飾の笈型や絵様など要所に濃密な彫刻を施し、時代的特色をよく表す。北方には桁行三間梁間二間の番所を付設する。本坊入口の厳格な雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010366"},{"id":"00010363","register_sub_id":"101","register_pk":"199135","name":"萩原寺客殿","kana":"はぎわらじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2742-1","lat":34.070828,"lng":133.687047,"geo_status":"db","era":"宝暦14年（1764）頃","year":1764,"year_source":"db","year_min":1764,"year_max":1764,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積241㎡、門付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0403","desc":"境内西側本坊の中心に東面して建つ大型客殿で、北端に唐破風屋根の式台を構えて御成門を従え、南側は西列に三室、東列に二室を配し、南西隅に上段の間を配する。屋根は茅葺の四方に瓦葺屋根を廻らす、当地で四方蓋と呼ぶ形式をもち、地方的特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010363"},{"id":"00010362","register_sub_id":"101","register_pk":"199134","name":"萩原寺護摩堂","kana":"はぎわらじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.071205,"lng":133.687839,"geo_status":"db","era":"江戸前期／享保10年（1725）・昭和10年頃・昭和58年改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0402","desc":"境内中央の山麓部に南面して建つ。方三間で宝形造の外陣の背面に切妻造の内陣を張出し、正面に一間向拝を付す。外陣は面取の大きい角柱に舟肘木を載せ、軒をせがい造として深くとる。内陣床下には石積みの護摩壇が設けられ、古来よりの信仰形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010362"},{"id":"00010364","register_sub_id":"101","register_pk":"199136","name":"萩原寺鐘楼","kana":"はぎわらじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.070863,"lng":133.688344,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0404","desc":"本堂へ登る石段の参道脇に建つ吹放ち形式の鐘楼で、入母屋造本瓦葺である。面取角柱を四方転びに立て、貫で繋ぐ。頭貫木鼻に獅子彫刻を飾り、頭貫上に台輪を廻して三斗を組み、中備に龍や波紋に彫刻化した蟇股を飾る。境内景観に寄与する端正な意匠の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010364"},{"id":"00010365","register_sub_id":"101","register_pk":"199137","name":"萩原寺手水舎","kana":"はぎわらじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.070914,"lng":133.688457,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、面積5.0㎡、手水鉢付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0405","desc":"本堂南方に東西棟で建つ切妻造本瓦葺の手水舎。石製礎盤上に角柱を四方転びに立て、頭貫と台輪を廻らして固める。四隅に皿斗付大斗の三斗を組み、桁と梁を受け、中備蟇股とする。軒は反りのある垂木を疎に配る。ケヤキの良材を使い、堅実な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010365"},{"id":"00010361","register_sub_id":"101","register_pk":"199133","name":"萩原寺本堂","kana":"はぎわらじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.07112,"lng":133.688428,"geo_status":"db","era":"享保8年（1723）／宝暦4年（1754）・昭和10年改修","year":1723,"year_source":"db","year_min":1723,"year_max":1723,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0401","desc":"境内東丘陵上に南面し、桁行五間梁間六間、正面三間向拝付、本瓦葺。内部は前後に二分し、内外陣とも三間梁を架けて無柱の室とする。粽付円柱に台輪を廻して三斗詰組とし、桟唐戸をたてるなど禅宗様を積極的に取入れており、近世密教系寺院仏堂の一様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010361"},{"id":"00010367","register_sub_id":"101","register_pk":"199139","name":"萩原寺南門及び土塀","kana":"はぎわらじみなみもんおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2742-1","lat":34.07075267,"lng":133.68742303,"geo_status":"db","era":"江戸末期／昭和53年・平成3年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"南門 木造、瓦葺、間口2.6m 土塀 土塀、瓦葺、総延長89m","structure_material":"南門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0407","desc":"境内本坊部分の東辺を画する土塀と、大門の南方にあけられた南門からなる。南門は一間薬医門の形式で、本柱、控柱とも丸太材を使用して野趣にあふれた景観を形成する。土塀は総延長八九メートルに及ぶ長大なもので、本坊の表構えに緊張感と格調を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010367"},{"id":"00013198","register_sub_id":"101","register_pk":"368422","name":"本堯寺松平頼該霊廟","kana":"ほんぎょうじまつだいらよりかねれいびょう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市西山崎町850-1","lat":34.275675,"lng":133.990425,"geo_status":"db","era":"明治元年／明治42年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡、無縫塔付","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"37 － 0444","desc":"高松藩松平家一門の頼該を祀る霊廟建築。無縫塔の墓石に一間四方で本瓦葺の宝形屋根をかけて奥殿と称し、四畳の寄棟造の拝殿とを二畳の相の間で繋ぐ。奥殿のみ丸柱に扇垂木として意匠を変える。複合社殿形式の武家廟所の遺例として希少である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013198"},{"id":"00009845","register_sub_id":"101","register_pk":"195674","name":"宮處八幡宮注連柱","kana":"みやどころはちまんぐうしめばしら","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30581477,"lng":134.11365662,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造、間口5.3m、脇柱付","structure_material":"石造","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0396","desc":"境内下段の石段上に建つ。見付〇・六メートル見込〇・五メートル、高さ四・二メートルの花崗石製の本柱一対を間口五・三メートルに立て、各々の両側に脇柱を立てて石貫で繋ぐ。本柱間には注連縄を張る。端正な意匠の注連柱で、境内入口の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009845"},{"id":"00009843","register_sub_id":"101","register_pk":"195672","name":"宮處八幡宮拝殿及び幣殿","kana":"みやどころはちまんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30610387,"lng":134.1138208,"geo_status":"db","era":"拝殿 明治11 幣殿 明治33","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0394","desc":"拝殿は桁行五間梁間二間、入母屋造本瓦葺で、正面に唐破風造の大振りな向拝を張出し、背面に両下造の幣殿を付属する。拝殿は外周に格子や舞良戸をたて、内部一室で格天井を張る。幣殿は二段階に床を高め、奥に本殿に昇段する階を備える。風格ある構えの拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009843"},{"id":"00009842","register_sub_id":"101","register_pk":"195671","name":"宮處八幡宮本殿","kana":"みやどころはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30616812,"lng":134.1138672,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、檜皮葺及び銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0393","desc":"高い石積基壇上に建ち、正面一間側面二間、入母屋造、正面向拝付、軒唐破風及び千鳥破風付、檜皮葺である。側背面に廻らした縁に五手先、正面の浜床に三手先の腰組を組み、軒は二軒で側背面を扇垂木とする。複雑な構成の細部を丁寧にまとめた見応えある近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009842"},{"id":"00009844","register_sub_id":"101","register_pk":"195673","name":"宮處八幡宮末社護国神社本殿","kana":"みやどころはちまんぐうまっしゃごこくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30606461,"lng":134.11363877,"geo_status":"db","era":"昭和11／昭和22移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0395","desc":"拝殿手前の参道の西側に祀られる。一間社流造、銅板葺で、正面に千鳥破風を飾る。四手先の腰組で縁を受け、花樹を透彫した脇障子を隅行に振り、意匠を強調する。また妻飾の大瓶束には花頭枠状の笈形を付す。小規模ながら手の込んだ造作になる境内社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009844"},{"id":"00014532","register_sub_id":"101","register_pk":"513946","name":"妙法寺山門（勅使門）","kana":"みょうほうじさんもん（ちょくしもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市富屋町9","lat":34.2898,"lng":133.795225,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造、瓦葺、間口3.1m、袖塀付","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0485","desc":"丸亀城北側の城下町に所在する天台宗寺院の四脚門。本堂正面の伽藍東面に開く。切妻造本瓦葺で多種の役瓦で飾る。一軒繁垂木で柱梁とも木柄太く重厚。門扉は欅一枚板に襷桟と寺紋付。主柱頭貫彫刻の波兎は見所で、虹梁や木鼻含めて塩飽大工による仕事は優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014532"},{"id":"00010374","register_sub_id":"101","register_pk":"199146","name":"本山寺冠木門","kana":"もとやまじかぶきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.13959756,"lng":133.69448894,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石造、間口4.4m、左右脇柱付","structure_material":"石造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0414","desc":"間口四・四メートルの石造冠木門で、両側に潜門を付属し、本堂東辺の入口を雄大に構成している。本柱は大面取の五平で、上細りの形状とし、冠木上部に帯を回して木瓜形を表し、頂部には唐破風造の屋根を載せるなど、丁寧に加工した花崗岩を精緻に組んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010374"},{"id":"00010369","register_sub_id":"101","register_pk":"199141","name":"本山寺十王堂","kana":"もとやまじじゅうおうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139669,"lng":133.693576,"geo_status":"db","era":"宝暦9年（1759）／平成5年改修","year":1759,"year_source":"db","year_min":1759,"year_max":1759,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0409","desc":"本堂の南西に東面し大師堂と対する。桁行五間梁間三間、寄棟造、三間向拝付の本瓦葺で、前一間を外陣、後方を内陣とし、背面の廊下と護摩堂が増築である。面取角柱を貫と長押で固めた軸部、大斗絵様肘木の組物は簡素であるが、向拝は架構や細部が充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010369"},{"id":"00010372","register_sub_id":"101","register_pk":"199144","name":"本山寺鐘楼","kana":"もとやまじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139223,"lng":133.693905,"geo_status":"db","era":"江戸中期","year":1661,"year_source":"db","year_min":1661,"year_max":1661,"year_label":null,"structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0412","desc":"境内南東部に位置し、乱石積基壇に建つ方一間吹放し形式の鐘楼。軒支輪付の二軒繁垂木とし、南北棟で入母屋造の本瓦葺をあげる。内転びに立てた粽付面取角柱を貫と台輪で固め、実肘木拳鼻付の出組を詰組にするなど、境内に相応しい充実した形式である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010372"},{"id":"00010368","register_sub_id":"101","register_pk":"199140","name":"本山寺大師堂","kana":"もとやまじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139378,"lng":133.694095,"geo_status":"db","era":"寛政7年（1795）／明治16年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0408","desc":"本堂南東に西面して建つ。方三間の入母屋造、一間向拝付で本瓦葺とする。前二間の外陣と後一間の内陣は格天井で、向拝と背面張出しが増築である。側まわりは面取角柱であるが、出組に中備平三斗、軒支輪付の本格的な形式で、境内復興整備の実像を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010368"},{"id":"00010370","register_sub_id":"101","register_pk":"199142","name":"本山寺大日堂","kana":"もとやまじだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139835,"lng":133.69398,"geo_status":"db","era":"江戸中期","year":1661,"year_source":"db","year_min":1661,"year_max":1661,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0410","desc":"本堂西脇の基壇に南面して建つ。方三間、宝形造本瓦葺で、内部は後一間に仏壇を構えた一室とし棹縁天井を張る。太い円柱や実肘木付三斗は風食などから室町期の材と判断されるが、長押や天井等が木細く、一八世紀中期に古材を利用して整備されたと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010370"},{"id":"00010373","register_sub_id":"101","register_pk":"199145","name":"本山寺大門","kana":"もとやまじだいもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139244,"lng":133.694063,"geo_status":"db","era":"江戸後期／大正3年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0413","desc":"大師堂南脇の八脚門。南北棟で入母屋造の本瓦葺、軒は二軒繁垂木とする。石製礎盤に円柱を立てて貫と虹梁、台輪で固め、組物は実肘木拳鼻付三斗、中備は正面各間と背面中央間が蟇股、ほかは撥束である。整った構造細部で、境内東面南方の構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010373"},{"id":"00010371","register_sub_id":"101","register_pk":"199143","name":"本山寺宝蔵","kana":"もとやまじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字屋敷内1359-31","lat":34.13974,"lng":133.694552,"geo_status":"db","era":"天保4年（1833）","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0411","desc":"本堂北の本坊東南に西面して建つ。土蔵造二階建、腰を海鼠壁とし、宝形造本瓦葺とする。西面に庇付出入口を設け、内壁は竪板張、一階は根太天井、二階は棹縁天井を張る。内外とも丁寧な造作になるが、正方形の平面や二階南面に設けた二連花頭窓は独特である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010371"},{"id":"00002690","register_sub_id":"101","register_pk":"103680","name":"乃木神社手水舎","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22548386,"lng":133.78058118,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.3㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0088","desc":"社務所の東南方，参道の鳥居をくぐりぬけた直ぐの左手に建つ。東西棟，銅板葺，切妻造，平入の手水舎で，四面吹放ちとする。柱は転びをつけず，２本宛の控柱を添えて貫，束，桁，梁などにより構成主義的な軸部を造作しているところに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002690"},{"id":"00003143","register_sub_id":"101","register_pk":"104133","name":"金両藤井家住宅正門（旧八幡寺山門）","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47645842,"lng":134.31826872,"geo_status":"db","era":"江戸後期／大正7頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0136","desc":"主屋玄関の東南方に位置し，土蔵の西南隅部につながる。間口９ｍ規模で，玄関に通じる大門，勘定場に対応する脇門，大門の西方の木戸門から構成される。大門は本瓦葺の１間１戸の薬医門で，廃寺となった八幡寺の山門を移築したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003143"},{"id":"00002696","register_sub_id":"101","register_pk":"103686","name":"石土神社の高灯籠（式年祭記念燈）","kana":"いしづちじんしゃのたかとうろう（しきねんさいきねんとう）","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県西条市小松町妙口甲727-2","lat":33.87892359,"lng":133.07905476,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、高さ9.5m","structure_material":"鉄筋コンクリート造","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0023","desc":"町北西部の山際にある，式年祭を記念して造られた灯籠。末広がりの約９．５ｍ高，下部直径約１．５ｍのＲＣ造構造物で，頂部にコンクリートでかたどった宝珠・笠・四面開放の火袋等を頂く。巡礼登山道の途中にあり，地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002696"},{"id":"00013764","register_sub_id":"101","register_pk":"505325","name":"西条栄光教会牧師館","kana":"さいじょうえいこうきょうかいぼくしかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県西条市明屋敷字旧陣屋内236-3","lat":33.92094444,"lng":133.17948333,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 152","desc":"礼拝堂の南に渡廊下で接続する。二階建切妻造桟瓦葺。下部を杉板張、上部を真壁造とする。玄関周囲に食堂や居間などを配し、玄関は吹抜の階段室を兼ね、二階は集会室、寝室などである。内外とも漆喰に木部を現し格子や障子を用いるなど和風意匠で統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013764"},{"id":"00013763","register_sub_id":"101","register_pk":"505323","name":"西条栄光教会礼拝堂","kana":"さいじょうえいこうきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県西条市明屋敷字旧陣屋内236-3","lat":33.92114722,"lng":133.17943889,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積197㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 151","desc":"西条藩の陣屋跡に位置。桁行二〇メートル梁間九メートル、切妻造桟瓦葺で両脇に下屋を設ける。南面中央に鐘塔を掲げ、妻の一部をやや前方に張出して十字架を付す。内部は一室の礼拝堂で奥に祭壇を設ける。白色の壁と縦長窓の連続が印象的なモダンな礼拝堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013763"},{"id":"00007598","register_sub_id":"101","register_pk":"108580","name":"浄光寺地蔵堂","kana":"じょうこうじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県越智郡上島町岩城855","lat":34.24715893,"lng":133.15039108,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"38 － 0088","desc":"本堂の東に南面して建つ小規模な仏堂。入母屋造本瓦葺。面取方柱が、直接に桁を受ける。一軒疎垂木。正面中央と側面前間に建具をたて、他を漆喰壁とし、正面から側面前寄りに切目縁をまわす。内部は広い１室。軒が全体にわたって反り、軽快な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007598"},{"id":"00007597","register_sub_id":"101","register_pk":"108579","name":"浄光寺本堂","kana":"じょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県越智郡上島町岩城855","lat":34.247128,"lng":133.150269,"geo_status":"db","era":"宝暦2／文政8改修","year":1752,"year_source":"db","year_min":1752,"year_max":1752,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"38 － 0087","desc":"南面して建つ三間堂。宝形造本瓦葺で、正面に一間向拝、背面に下屋を付ける。面取方柱で、木鼻付大斗絵様肘木とし、中備に蓑束を飾る。一軒繁垂木。内部は前寄り二間通りを外陣、その奥を内陣とし、中央後寄りに須弥壇を置く。小規模な浄土宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007597"},{"id":"00005205","register_sub_id":"101","register_pk":"106195","name":"福田寺山門","kana":"ふくでんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市上吾川878","lat":33.74559314,"lng":132.7156639,"geo_status":"db","era":"文政5","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0069","desc":"切妻造，本瓦葺の四脚門で，本堂南に東面して建つ。総欅の素木造で，軸部は親柱が円柱，控柱が角柱，組物は実肘木付三斗，中備が蟇股，妻飾は虹梁大瓶束で，軒は二軒繁垂木である。虹梁や木鼻の渦文，笈形の波濤文，持送り彫物など，装飾細部も充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005205"},{"id":"00005204","register_sub_id":"101","register_pk":"106194","name":"福田寺通玄庵","kana":"ふくでんじつうげんあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市上吾川878","lat":33.74571052,"lng":132.71556331,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0068","desc":"本堂南西に南面して建つ。寄棟造，茅葺の四周に瓦葺の下屋を廻した，いわゆる四方蓋造の外観を呈する。南東隅に玄関，その北にダイドコ，西側に田の字形で４室を配し，北西の仏間の天井に龍を描く。隠居した僧侶の住居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005204"},{"id":"00005203","register_sub_id":"101","register_pk":"106193","name":"福田寺本堂","kana":"ふくでんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市上吾川878","lat":33.74592838,"lng":132.7157949,"geo_status":"db","era":"天明元","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0067","desc":"南北に細長い境内に南面して建つ。入母屋造，本瓦葺で，妻飾は狐格子とする。基本的には６間取平面になり，正面に広縁を設ける。組物や彫物を用いないが，内陣仏壇の構えや，室中と両脇間の境に設けた竹の節欄間など，方丈形式のつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005203"},{"id":"00003156","register_sub_id":"101","register_pk":"104146","name":"ふるさと旅行村極楽堂","kana":"ふるさとりょこうむらごくらくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県上浮穴郡久万高原町下畑野川乙488","lat":33.67318641,"lng":132.93736021,"geo_status":"db","era":"明治31／昭和52移築","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0033","desc":"三間四方の平面に宝形造の屋根を載せる堂宇で，四方に濡縁を巡らす。正面は２間幅の扉口を開き，他は横板壁とする。内部は格天井に郷土の植物画を描く。地元組中の集会所的施設でもあり、当初四国遍路の道筋にあったことから仮眠の宿としても利用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003156"},{"id":"00015516","register_sub_id":"101","register_pk":"533531","name":"明専寺石垣","kana":"みょうせんじいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県今治市大西町脇甲1277","lat":34.05773333,"lng":132.91892778,"geo_status":"db","era":"天保9年（1838）／安政4年（1857）増築","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"石造、総延長83m","structure_material":"石造","registered":"2025.08.06(令和7.08.06)","register_no":"38 - 0200","desc":"境内東面の市道に沿った石垣。総延長八三メートル、最大高さ約二・五メートル、中央石段を挟み北側は弓杖島の花崗岩、南側は寺周囲から集めた様々な石を用い、いずれも村中寄進で築造した。大小の石を精緻に積んだ長大な石垣で、地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015516"},{"id":"00015515","register_sub_id":"101","register_pk":"533530","name":"明専寺鐘楼門","kana":"みょうせんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県今治市大西町脇甲1277","lat":34.0579,"lng":132.91891389,"geo_status":"db","era":"天保11年（1840）","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造2階建、瓦葺、建築面積8.3㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"38 - 0199","desc":"市街西方の丘陵地に位置する浄土真宗寺院の鐘楼門。一間一戸二重門で入母屋造本瓦葺。下層は桁先を延ばして軒桁を支持。上層組物は出組、軒は二軒繁垂木。側廻りは連子窓で正背面中央間を開放とし内部に梵鐘を吊る。彫刻は幕末の時代相応で境内入口を飾る門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015515"},{"id":"00006327","register_sub_id":"101","register_pk":"107310","name":"明石寺石垣及び塀","kana":"めいせきじいしがきおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36909985,"lng":132.51928004,"geo_status":"db","era":"昭和5・昭和19","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石垣 石造、総延長73m、石段付 塀 石造、総延長63m","structure_material":"石垣 石造","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0083","desc":"本堂のある最上段の敷地を形成する。石垣は高さ３．８ｍ、石段付。積み方は打込矧ぎの乱積で、出隅部は算木積で反りを付ける。石垣上の塀は鉄筋コンクリート造で擬宝珠高欄状に造り、柱間の花頭窓風に透かした意匠が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006327"},{"id":"00006328","register_sub_id":"101","register_pk":"107311","name":"明石寺石段及び石垣","kana":"めいせきじいしだんおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.3685981,"lng":132.5194425,"geo_status":"db","era":"大正5・大正期／昭和初期増設","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石段 石造43段、幅3.7m、石垣 石造、総延長65m","structure_material":"石段 石造43段","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0084","desc":"石段は幅３．６ｍ、踊場を設けた４３段から成り、仁王門の前に至る。御影石の切石を用い、階段曲線部は３石を継ぎ、直線部は１石で１段とする。石垣は境内中段の平地を造成。野面石を用いた乱積で、西側の一部は矢羽積。傾斜地を利用した境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006328"},{"id":"00006326","register_sub_id":"101","register_pk":"107309","name":"明石寺客殿","kana":"めいせきじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.368847,"lng":132.519409,"geo_status":"db","era":"大正期／昭和42頃改造","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0080","desc":"仁王門の南東、北面して建つ。桁行８間、梁間５間、入母屋造、桟瓦葺で、正面西端に唐破風造の式台を付ける。内部は大床付の４８畳や式台の間、事務所ほかを設け、南側東端に茶室に付設。質実な意匠で、落ち着いた外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006326"},{"id":"00006323","register_sub_id":"101","register_pk":"107306","name":"明石寺地蔵堂","kana":"めいせきじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36904578,"lng":132.51929978,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0078","desc":"境内中段の平地に位置し、南面して建つ。桁行３間、梁間３間、入母屋造、桟瓦葺で正面に向拝を設ける。組物は二手先、軒は二軒繁垂木、妻飾は虹梁大瓶束とする。龍や兎、鶴などの彫刻が向拝や身舎の細部にわたり施され、彫物師の意気込みが伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006323"},{"id":"00006322","register_sub_id":"101","register_pk":"107305","name":"明石寺鐘楼堂","kana":"めいせきじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36917067,"lng":132.51918722,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積9.2㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0081","desc":"本堂の南東に位置し、基壇上に建つ。桁行１間、梁間１間、四方吹放ち鐘楼で、入母屋造、桟瓦葺とする。円柱は内転びに建て、三斗組で、中備にも平三斗を置き、二軒繁垂木とする。装飾を抑えた意匠とするが、軒の出が深く、入母屋屋根の反りが美しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006322"},{"id":"00006321","register_sub_id":"101","register_pk":"107304","name":"明石寺大師堂","kana":"めいせきじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36931322,"lng":132.51915722,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0077","desc":"本堂の東に並んで南面して建つ。方３間宝形造、桟瓦葺。組物は出三斗、軒は二軒繁垂木。向拝の獅子彫刻とした木鼻や、身舎の雲形に彫り込まれた支輪板など装飾的である。また向拝部分の飛檐垂木をＳ字状の反転曲線とし、向拝軒勾配を調整する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006321"},{"id":"00006325","register_sub_id":"101","register_pk":"107308","name":"明石寺手水舎","kana":"めいせきじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36880111,"lng":132.51910011,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、面積5.5㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0082","desc":"仁王門の南西に位置する。切妻造、銅板葺。方柱４本を内転びに建て、中央に手水鉢を置き、四方吹放ちとする。三斗組で、軒は二軒繁垂木とし、妻飾は虹梁大瓶束で笈形を付ける。小規模ながら、建築的細部を丁寧に仕上げた佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006325"},{"id":"00006324","register_sub_id":"101","register_pk":"107307","name":"明石寺仁王門","kana":"めいせきじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36888844,"lng":132.51907667,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0079","desc":"本堂の前方、境内中段の平地に位置し、南面して建つ。３間１戸八脚門で、入母屋造、桟瓦葺とする。出組で二軒繁垂木。正面は頭貫を全て虹梁形とし、欄間や支輪板に雲紋を彫り込み、大棟は両端に鯱を配し、側板は波や龍に型取るなど、意匠、技術ともに優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006324"},{"id":"00006320","register_sub_id":"101","register_pk":"107303","name":"明石寺本堂","kana":"めいせきじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36922656,"lng":132.51898711,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0076","desc":"山の斜面に位置する境内最上段に、南面して建つ。桁行５間、梁間５間、入母屋造、桟瓦葺、向拝付。四方に切目縁を廻し、組物は平三斗、軒は二軒繁垂木。唐破風屋根を大屋根の下で突き出す重厚な外観と、向拝の随所に施された彫刻が目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006320"}];
